      background-image:
        radial-gradient(ellipse 2.6px 1.8px at center, var(--track-dot-off) 64%, transparent 70%);
      background-position: 0 50%;
    }
    .metric-fill {
      position: absolute;
      inset: 0  auto 0 0;
      width: var(--fill);
      background: transparent;
      background-image:
        radial-gradient(circle at center, var(--track-dot-on) 1px, transparent 1px);
      background-size: var(--metric-track-size) var(--metric-track-size);
      background-position: 0 calc(50% - 0.5px);
      min-width: 1px;
    }

    .today-shell.mode-full .metric-fill {
      background-image:
        radial-gradient(ellipse 2.6px 1.8px at center, var(--track-dot-on) 65%, transparent 71%);
      background-position: 0 50%;
    }

    .today-shell.mode-full .metric-fill::after {
      content: '';
      position: absolute;
