  {% assign custom_days_until = custom_seconds_until | divided_by: 86400 %}
  {% if custom_days_until < 0 %}
    {% assign custom_days_until = 0 %}
  {% endif %}
  {% assign custom_progress = custom_days_until | times: 100.0 | divided_by: 365 | round %}
  {% assign custom_progress = 100 | minus: custom_progress %}
  {% if custom_progress < 0 %}
    {% assign custom_progress = 0 %}
  {% elsif custom_progress > 100 %}
