{% assign event_label = '' %}
{% assign event_kind = 'spark' %}
{% assign next_holiday_label = '' %}
{% assign next_holiday_date = '' %}
{% assign next_holiday_fallback_label = '' %}
{% assign next_holiday_fallback_date = '' %}

{% if feed_has_entries %}
  {% for holiday in holiday_feed %}
    {% assign holiday_date = holiday.date | default: '' %}
    {% if holiday_date > today_iso and next_holiday_fallback_date == blank %}
      {% assign fallback_label = holiday.localName | default: holiday.name | default: '' %}
      {% if locale_lang == 'en' %}
        {% assign fallback_label = holiday.name | default: holiday.localName | default: '' %}
      {% endif %}
      {% assign next_holiday_fallback_date = holiday_date %}
      {% assign next_holiday_fallback_label = fallback_label %}
    {% endif %}
    {% assign holiday_country = holiday.countryCode | default: '' | upcase %}
