        {% endif %}

        {% if holiday_date == today_iso and event_label == blank %}
          {% assign event_label = holiday_label %}
        {% endif %}

        {% if holiday_date > today_iso and next_holiday_date == blank %}
          {% assign next_holiday_date = holiday_date %}
          {% assign next_holiday_label = holiday_label %}
        {% endif %}
      {% endif %}
    {% endif %}
  {% endfor %}
