    {% endif %}

    {% assign holiday_country = holiday.countryCode | default: '' | upcase %}
    {% if holiday_country == country_key %}
      {% assign region_match = false %}
      {% if holiday.counties == blank %}
        {% assign region_match = true %}
      {% elsif region_code != blank and holiday.counties contains region_code %}
        {% assign region_match = true %}
      {% endif %}

      {% if region_match %}
        {% assign holiday_label = holiday.localName | default: holiday.name | default: '' %}
        {% if locale_lang == 'en' %}
          {% assign holiday_label = holiday.name | default: holiday.localName | default: '' %}
        {% endif %}

        {% if holiday_date > today_iso and next_holiday_date == blank %}
          {% assign next_holiday_date = holiday_date %}
          {% assign next_holiday_label = holiday_label %}
        {% endif %}
      {% endif %}
    {% endif %}
  {% endfor %}
{% endif %}
{% if next_holiday_date == blank and next_holiday_fallback_date != blank %}
  {% assign next_holiday_date = next_holiday_fallback_date %}
  {% assign next_holiday_label = next_holiday_fallback_label %}
