      flex: 0 0 auto;
    }

    .metric-pill-icon svg {
      width: 100%;
      height: 100%;
      stroke: currentColor;
      fill: none;
      stroke-width: 1.65;
      stroke-linecap: round;
      stroke-linejoin: round;
    }

    .metric-pill-text {
      display: block;
      min-width: 0;
      max-width: 13ch;
      overflow: hidden;
      text-overflow: ellipsis;
