    .today-shell.mode-half-vertical .metric-fill {
      background-image:
        radial-gradient(ellipse 2.1px 1.45px at center, var(--track-dot-on) 65%, transparent 71%);
      background-position: 0 50%;
    }
    .today-shell.mode-half-vertical .metric-fill::after {
      content: '';
      position: absolute;
      top: 0;
      bottom: 0;
      right: 0;
      width: 2px;
      background: var(--track-dot-on);
      opacity: 0.9;
