<script>
(() => {
  const rootNode = document.querySelector('.today-shell.mode-half-vertical');
  const FORCE_LIGHT_MODE_RAW = {{ trmnl.plugin_settings.custom_fields_values.force_light_mode | default: force_light_mode | default: "false" | json }};
  const FORCE_LIGHT_MODE = /^(1|true|yes|on)$/i.test(String(FORCE_LIGHT_MODE_RAW));

  const applyModeTone = () => {
    if (!rootNode) {
      return;
    }
    if (FORCE_LIGHT_MODE) {
      rootNode.classList.add('is-mode-light', 'is-force-light');
      return;
    }
    rootNode.classList.remove('is-mode-light', 'is-force-light');
  };

  applyModeTone();

  const glyphs = {
    '0': ['01110', '10001', '10001', '10001', '10001', '10001', '01110'],
    '1': ['00100', '01100', '10100', '00100', '00100', '00100', '11110'],
    '2': ['11111', '00001', '00001', '01111', '10000', '10000', '11111'],
    '3': ['11111', '00001', '00001', '01110', '00001', '00001', '11110'],
    '4': ['10001', '10001', '10001', '11111', '00001', '00001', '00001'],
    '5': ['11111', '10000', '10000', '11110', '00001', '00001', '11110'],
    '6': ['01110', '10000', '10000', '11110', '10001', '10001', '01110'],
    '7': ['11111', '00001', '00010', '00100', '01000', '01000', '01000'],
    '8': ['01110', '10001', '10001', '01110', '10001', '10001', '01110'],
    '9': ['01110', '10001', '10001', '01111', '00001', '00001', '01110'],
    '+': ['00100', '00100', '11111', '00100', '00100', '00000', '00000'],
    '-': ['00000', '00000', '11111', '00000', '00000', '00000', '00000'],
    '.': ['00000', '00000', '00000', '00000', '00000', '00100', '00000'],
    ':': ['00000', '00100', '00100', '00000', '00000', '00100', '00100'],
    '%': ['10001', '10010', '00010', '00100', '01000', '10010', '10001'],
    ' ': ['00000', '00000', '00000', '00000', '00000', '00000', '00000']
  };

  const renderNode = (node) => {
    const text = String(node.dataset.dotText || '').toUpperCase();
    if (!text) {
      return;
    }

    const scale = parseFloat(node.dataset.dotScale);
    const cell = Number.isFinite(scale) && scale > 0 ? scale : 1.4;
    const columns = 6;
    const rows = 7;
    const spacing = 1;
    const svgWidth = (text.length * columns - spacing) * cell;
    const svgHeight = rows * cell;

    const ns = 'http://www.w3.org/2000/svg';
    const svg = document.createElementNS(ns, 'svg');
    svg.setAttribute('viewBox', `0 0 ${svgWidth} ${svgHeight}`);
    svg.setAttribute('width', `${svgWidth}`);
    svg.setAttribute('height', `${svgHeight}`);
    svg.setAttribute('aria-hidden', 'true');
    svg.setAttribute('class', 'dot-matrix-glyph');

    const onRadius = Math.max(0.8, cell * 0.44);
    const offRadius = Math.max(0.34, cell * 0.19);

    for (let i = 0; i < text.length; i++) {
      const glyph = glyphs[text[i]] || glyphs[' '];

      for (let row = 0; row < rows; row++) {
        const line = glyph[row] || '00000';
        for (let col = 0; col < 5; col++) {
          const bit = line[col] === '1';
          const dot = document.createElementNS(ns, 'circle');
          dot.setAttribute('cx', `${(i * columns + col + 0.5) * cell}`);
          dot.setAttribute('cy', `${(row + 0.5) * cell}`);
          dot.setAttribute('r', `${bit ? onRadius : offRadius}`);
          dot.setAttribute('class', bit ? 'dot-on' : 'dot-off');
          svg.appendChild(dot);
        }
      }
    }

    node.textContent = '';
    node.appendChild(svg);
  };

  document.querySelectorAll('.dot-text').forEach(renderNode);

  document.querySelectorAll('.metric-track[data-fill]').forEach((track) => {
    const raw = parseFloat(track.dataset.fill || '0');
    const bounded = Number.isFinite(raw) ? Math.max(0, Math.min(100, raw)) : 0;
    track.style.setProperty('--fill', bounded + '%');
  });
})();
</script>
","half_horizontal":"{% assign now = 'now' %}
{% assign now_epoch = trmnl.system.timestamp_utc | default: '' %}
{% if now_epoch != blank %}
  {% assign now_epoch = now_epoch | plus: 0 %}
  {% assign utc_offset_raw = trmnl.user.utc_offset | default: 0 | plus: 0 %}
  {% assign utc_offset_seconds = utc_offset_raw | times: 3600 %}
  {% if utc_offset_raw > 24 or utc_offset_raw < -24 %}
    {% assign utc_offset_seconds = utc_offset_raw %}
  {% endif %}
  {% assign local_epoch = now_epoch | plus: utc_offset_seconds %}
  {% assign now = local_epoch %}
{% endif %}
{% assign year = now | date: '%Y' | plus: 0 %}
{% assign year_text = now | date: '%Y' %}
{% assign month_short = now | date: '%b' | upcase %}
{% assign week_of_year = now | date: '%V' %}
{% assign week_label = 'W' | append: week_of_year %}
{% assign weekday_index = now | date: '%w' | plus: 0 %}
{% assign weekday_name = now | date: '%A' | upcase %}
{% assign month_name = now | date: '%B' | upcase %}
{% assign day_of_month = now | date: '%d' | plus: 0 %}
{% assign day_of_year = now | date: '%j' | plus: 0 %}
{% assign month_num = now | date: '%m' | plus: 0 %}
{% assign today_iso = now | date: '%Y-%m-%d' %}

{% assign month_days = 30 %}
{% assign leap4 = year | modulo: 4 %}
{% assign leap100 = year | modulo: 100 %}
{% assign leap400 = year | modulo: 400 %}

{% if month_num == 2 %}
  {% if leap4 == 0 and leap100 != 0 or leap400 == 0 %}
    {% assign month_days = 29 %}
  {% else %}
    {% assign month_days = 28 %}
  {% endif %}
{% elsif month_num == 1 or month_num == 3 or month_num == 5 or month_num == 7 or month_num == 8 or month_num == 10 or month_num == 12 %}
  {% assign month_days = 31 %}
{% endif %}

{% assign is_leap_year = false %}
{% if leap4 == 0 and leap100 != 0 or leap400 == 0 %}
  {% assign is_leap_year = true %}
{% endif %}
{% assign days_in_year = 365 %}
{% if is_leap_year %}
  {% assign days_in_year = 366 %}
{% endif %}

{% assign week_progress = weekday_index | plus: 1 | times: 100.0 | divided_by: 7 | round %}
{% assign month_progress = day_of_month | times: 100.0 | divided_by: month_days | round %}
{% assign year_progress = day_of_year | times: 100.0 | divided_by: days_in_year | round %}

{% if week_progress < 0 %}
  {% assign week_progress = 0 %}
{% elsif week_progress > 100 %}
  {% assign week_progress = 100 %}
{% endif %}
{% if month_progress < 0 %}
  {% assign month_progress = 0 %}
{% elsif month_progress > 100 %}
  {% assign month_progress = 100 %}
{% endif %}
{% if year_progress < 0 %}
  {% assign year_progress = 0 %}
{% elsif year_progress > 100 %}
  {% assign year_progress = 100 %}
{% endif %}

{% assign has_data = true %}
{% if day_of_month == 0 or month_days == 0 %}
  {% assign has_data = false %}
{% endif %}

{% assign custom_target_label_input = trmnl.plugin_settings.custom_fields_values.custom_countdown_label | default: '' | strip %}
{% assign custom_target_label = custom_target_label_input | upcase %}
{% if custom_target_label == blank %}
  {% assign custom_target_label = 'TARGET' %}
{% endif %}
{% assign custom_target_label = custom_target_label | slice: 0, 10 %}

{% assign custom_target_raw = trmnl.plugin_settings.custom_fields_values.custom_countdown_date | default: '' | strip %}
{% assign custom_has_target = false %}
{% assign custom_days_until = 0 %}
{% assign custom_progress = 0 %}

{% assign custom_parts = custom_target_raw | split: '-' %}
{% if custom_parts.size == 3 %}
  {% assign custom_year_text = custom_parts[0] | strip %}
  {% assign custom_month_text = custom_parts[1] | strip %}
  {% assign custom_day_text = custom_parts[2] | strip %}
  {% assign custom_year = custom_year_text | plus: 0 %}
  {% assign custom_month = custom_month_text | plus: 0 %}
  {% assign custom_day = custom_day_text | plus: 0 %}
  {% assign custom_month_days = 30 %}
  {% assign custom_leap4 = custom_year | modulo: 4 %}
  {% assign custom_leap100 = custom_year | modulo: 100 %}
  {% assign custom_leap400 = custom_year | modulo: 400 %}

  {% if custom_month == 2 %}
    {% if custom_leap4 == 0 and custom_leap100 != 0 or custom_leap400 == 0 %}
      {% assign custom_month_days = 29 %}
    {% else %}
      {% assign custom_month_days = 28 %}
    {% endif %}
  {% elsif custom_month == 1 or custom_month == 3 or custom_month == 5 or custom_month == 7 or custom_month == 8 or custom_month == 10 or custom_month == 12 %}
    {% assign custom_month_days = 31 %}
  {% endif %}

  {% assign custom_year_size = custom_year_text | size %}
  {% if custom_year_size == 4 and custom_month >= 1 and custom_month <= 12 and custom_day >= 1 and custom_day <= custom_month_days %}
    {% assign custom_has_target = true %}
  {% endif %}
{% endif %}

{% if custom_has_target %}
  {% assign custom_target_iso = custom_target_raw | date: '%Y-%m-%d' %}
  {% assign today_epoch = today_iso | date: '%s' | plus: 0 %}
  {% assign custom_target_epoch = custom_target_iso | date: '%s' | plus: 0 %}
  {% assign custom_seconds_until = custom_target_epoch | minus: today_epoch %}
  {% assign custom_days_until = custom_seconds_until | divided_by: 86400 %}
  {% if custom_days_until < 0 %}
