    {% assign utc_offset_seconds = utc_offset_raw %}
  {% endif %}
  {% assign local_epoch = now_epoch | plus: utc_offset_seconds %}
  {% assign now = local_epoch %}
{% endif %}
{% assign year = now | date: '%Y' | plus: 0 %}
{% assign year_text = now | date: '%Y' %}
{% assign month_short = now | date: '%b' | upcase %}
