      MARGIN: 0;
      MARGIN-top: clamp(6px, 0.9vh, 12px);
      display: flex;
      align-items: center;
      JUSTIFY-CONTENT: center;
      gap: 0.36rem;
      color: var(--panel-sub);
      FONT-SIZE: clamp(0.5rem, 1.45vh, 0.7rem);
      letter-spacing: 0.06em;
      line-height: 1.2;
      text-transform: none;
      min-width: 0;
    }

    .next-holiday .next-tag {
      color: var(--panel-fg);
      font-weight: 700;
      letter-spacing: 0.14em;
      text-transform: uppercase;
      MARGIN-right: 0;
      flex: 0 0 auto;
    }

    .next-holiday-icon {
      width: clamp(11px, 1.45vh, 15px);
      height: clamp(11px, 1.45vh, 15px);
      border: 1px solid var(--panel-border);
      BORDER-RADIUS: 999px;
      display: inline-flex;
      align-items: center;
      JUSTIFY-CONTENT: center;
      box-sizing: border-box;
      flex: 0 0 auto;
    }

    .next-holiday-icon svg {
      width: 72%;
      height: 72%;
      stroke: var(--panel-fg);
      fill: none;
      stroke-width: 1.7;
      stroke-linecap: round;
      stroke-linejoin: round;
    }

    .next-holiday .next-copy {
      min-width: 0;
      overflow: hidden;
      text-overflow: ellipsis;
      white-space: nowrap;
    }

    .next-holiday.feed-offline {
      color: var(--panel-fg);
      letter-spacing: 0.12em;
      text-transform: uppercase;
    }
    .today-shell.mode-quadrant .next-holiday {
      MARGIN-top: clamp(2px, 0.45vh, 5px);
      FONT-SIZE: clamp(0.5rem, 1.35vh, 0.7rem);
      JUSTIFY-CONTENT: center;
    }

    .today-shell.mode-quadrant.is-og .next-holiday {
      MARGIN-top: 1px;
      FONT-SIZE: clamp(0.34rem, 0.82vh, 0.44rem);
      gap: 0.18rem;
      line-height: 1;
    }

    .metrics-panel {
      display: flex;
      flex-direction: column;
      JUSTIFY-CONTENT: flex-end;
      gap: var(--row-gap);
      PADDING: calc(var(--pad) * 0.55) calc(var(--pad) * 0.58);
      box-sizing: border-box;
    }
    .today-shell.mode-quadrant .metrics-panel {
      position: absolute;
      left: 0;
      right: 0;
      top: calc(50% + var(--bars-offset));
      transform: translateY(-50%);
      JUSTIFY-CONTENT: flex-start;
      gap: clamp(2px, 0.45vh, 5px);
      align-items: stretch;
      PADDING-left: var(--stack-x);
      PADDING-right: var(--stack-x);
      PADDING-top: 0;
      PADDING-bottom: 0;
      border: 0;
      BORDER-RADIUS: 0;
      background: transparent;
    }

    .today-shell.mode-quadrant.is-og .metrics-panel {
      top: auto;
      bottom: 6px;
      gap: 0;
      transform: none;
    }
    .today-shell.mode-quadrant .metrics-panel::before {
      display: none;
    }

    .metric-row {
      display: grid;
      grid-template-columns: auto 1fr auto;
      gap: 0.5rem;
      align-items: center;
      min-width: 0;
    }
    .today-shell.mode-quadrant .metric-row {
      align-items: center;
      grid-template-columns: var(--metric-pill-w) 1fr var(--metric-value-w);
      gap: 1px;
    }

    .today-shell.mode-quadrant.is-og .metric-row {
      gap: 0;
    }

    .metric-pill {
      display: inline-flex;
      align-items: center;
      gap: 0.3rem;
      border: 0;
      BORDER-RADIUS: var(--badge-radius);
      PADDING: 0.08rem 0.46rem;
      line-height: 1;
      FONT-SIZE: var(--pill-size);
      letter-spacing: 0.2em;
      color: var(--panel-sub);
      font-weight: 600;
      white-space: nowrap;
      min-width: 0;
      align-self: center;
      background: var(--badge-bg);
      position: relative;
      box-sizing: border-box;
    }

    .metric-pill::after {
      content: '';
      position: absolute;
      top: 1px;
      right: 0;
      bottom: 1px;
      left: 0;
      border: 1px solid var(--badge-border);
      BORDER-RADIUS: calc(var(--badge-radius) - 1px);
      pointer-events: none;
    }
    .today-shell.mode-quadrant .metric-pill {
      border: 0;
      BORDER-RADIUS: var(--badge-radius);
      PADDING: 0.18rem 0.62rem 0.2rem;
      letter-spacing: 0.08em;
      color: var(--panel-fg);
      font-weight: 700;
      background: var(--badge-bg);
      JUSTIFY-CONTENT: center;
    }

    .today-shell.mode-quadrant.is-og .metric-pill {
      PADDING: 0.14rem 0.42rem 0.15rem;
      letter-spacing: 0.07em;
    }
    .metric-pill-icon {
      width: clamp(9px, 1.2vh, 13px);
      height: clamp(9px, 1.2vh, 13px);
      display: inline-flex;
      align-items: center;
      JUSTIFY-CONTENT: center;
      flex: 0 0 auto;
    }

    .metric-pill-icon svg {
      width: 100%;
      height: 100%;
      stroke: currentColor;
      fill: none;
      stroke-width: 1.65;
      stroke-linecap: round;
      stroke-linejoin: round;
    }

    .metric-pill-text {
      display: block;
      min-width: 0;
      max-width: 13ch;
      overflow: hidden;
      text-overflow: ellipsis;
      white-space: nowrap;
    }

    .metric-track-wrap {
      min-width: 0;
      width: 100%;
      align-self: center;
    }
    .today-shell.mode-quadrant .metric-track-wrap {
      width: 100%;
      grid-column: 2;
      grid-row: 1;
    }

    .metric-track {
      position: relative;
      width: 100%;
      height: var(--track-h);
      border: 0;
      BORDER-RADIUS: 0;
      background: transparent;
      background-image:
        radial-gradient(circle at center, var(--track-dot-off) 1px, transparent 1px);
      background-size: var(--metric-track-size) var(--metric-track-size);
      background-position: 0 calc(50% - 0.5px);
      overflow: hidden;
      box-sizing: border-box;
    }

    .metric-track::after {
      content: none;
    }
    .today-shell.mode-quadrant .metric-track {
      background-image:
        radial-gradient(ellipse 1.75px 1.2px at center, var(--track-dot-off) 64%, transparent 70%);
      background-position: 0 50%;
    }
    .metric-fill {
      position: absolute;
      inset: 0  auto 0 0;
      width: var(--fill);
      background: transparent;
      background-image:
        radial-gradient(circle at center, var(--track-dot-on) 1px, transparent 1px);
      background-size: var(--metric-track-size) var(--metric-track-size);
      background-position: 0 calc(50% - 0.5px);
      min-width: 1px;
    }
    .today-shell.mode-quadrant .metric-fill {
      background-image:
        radial-gradient(ellipse 1.75px 1.2px at center, var(--track-dot-on) 65%, transparent 71%);
      background-position: 0 50%;
    }
    .today-shell.mode-quadrant .metric-fill::after {
      content: '';
      position: absolute;
      top: 0;
      bottom: 0;
      right: 0;
      width: 2px;
      background: var(--track-dot-on);
      opacity: 0.9;
    }

    .metric-value {
      display: inline-flex;
      align-items: center;
      JUSTIFY-CONTENT: center;
      gap: 0.14rem;
      min-width: 3.75rem;
      TEXT-ALIGN: center;
      FONT-SIZE: var(--value-size);
      letter-spacing: 0.08em;
      line-height: 1;
      font-weight: 700;
      color: var(--panel-fg);
      justify-self: end;
      align-self: center;
      transform: none;
      PADDING: 0.18rem 0.46rem 0.2rem;
      border: 0;
      BORDER-RADIUS: var(--badge-radius);
      background: var(--badge-bg);
      position: relative;
      box-sizing: border-box;
    }

    .metric-value::after {
      content: '';
      position: absolute;
      top: 1px;
      right: 0;
      bottom: 1px;
      left: 0;
      border: 1px solid var(--badge-border);
      BORDER-RADIUS: calc(var(--badge-radius) - 1px);
      pointer-events: none;
    }
    .today-shell.mode-quadrant .metric-value {
      grid-column: 3;
      grid-row: 1;
      width: var(--metric-value-w);
      min-width: var(--metric-value-w);
      max-width: var(--metric-value-w);
