      <span class="event-icon" aria-hidden="true">
        {% if event_kind == 'women' %}
        <svg viewBox="0 0 16 16" role="img" aria-hidden="true"><circle cx="8" cy="5.5" r="3.4"></circle><path d="M8 8.9v5.4"></path><path d="M5.6 11.9h4.8"></path></svg>
        {% elsif event_kind == 'heart' %}
        <svg viewBox="0 0 16 16" role="img" aria-hidden="true"><path d="M8 13.3 3.3 8.6a2.8 2.8 0 1 1 4-4l.7.7.7-.7a2.8 2.8 0 1 1 4 4Z"></path></svg>
        {% elsif event_kind == 'leaf' %}
        <svg viewBox="0 0 16 16" role="img" aria-hidden="true"><path d="M13.4 2.6c-4.6.2-7.7 2.1-8.9 5.8-.6 1.8-.6 3.6-.3 4.9 1.4.3 3.2.3 4.9-.3 3.7-1.2 5.6-4.3 5.8-8.9z"></path><path d="M4.7 11.3 10.8 5.2"></path></svg>
