        {% elsif event_kind == 'poppy' %}
        <svg viewBox="0 0 16 16" role="img" aria-hidden="true"><circle cx="6.1" cy="7.8" r="2.2"></circle><circle cx="9.9" cy="7.8" r="2.2"></circle><circle class="fill" cx="8" cy="7.8" r="1.1"></circle><path d="M8 8.9v4.4"></path></svg>
        {% elsif event_kind == 'peace' %}
        <svg viewBox="0 0 16 16" role="img" aria-hidden="true"><circle cx="8" cy="8" r="6"></circle><path d="M8 2v12"></path><path d="m8 8-3.3 3.3"></path><path d="M8 8l3.3 3.3"></path></svg>
        {% elsif event_kind == 'alert' %}
        <svg viewBox="0 0 16 16" role="img" aria-hidden="true"><path d="M8 2.2 14 13H2z"></path><path class="fill" d="M7.4 6h1.2v3.9H7.4z"></path><circle class="fill" cx="8" cy="11.5" r="0.85"></circle></svg>
        {% elsif event_kind == 'flag' %}
