        {% else %}
        <svg viewBox="0 0 16 16" role="img" aria-hidden="true"><path d="M8 2.2 9.4 6l4 .4-3 2.5.9 3.9L8 10.9 4.7 12.8l.9-3.9-3-2.5 4-.4z"></path></svg>
        {% endif %}
      </span>
      <span class="event-label">{{ event_label }}</span>
