  </section>

  {% if has_data %}
  <section class="panel metrics-panel">
    <div class="metric-row">
      <span class="metric-pill"><span class="metric-pill-icon" aria-hidden="true"><svg viewBox="0 0 16 16" role="img" aria-hidden="true"><path d="M2.5 4.2h11"></path><path d="M2.5 8h11"></path><path d="M2.5 11.8h7.2"></path></svg></span><span class="metric-pill-text">{{ week_label }}</span></span>
      <div class="metric-track-wrap">
        <div class="metric-track" data-fill="{{ week_progress }}">
          <span class="metric-fill"></span>
        </div>
      </div>
      <span class="metric-value" aria-label="Week progress {{ week_progress }} percent"><span class="dot-text" data-dot-text="{{ week_progress }}" data-dot-scale="{{ metric_dot_scale }}" aria-label="{{ week_progress }}">{{ week_progress }}</span><span class="metric-unit">%</span></span>
    </div>

    <div class="metric-row">
      <span class="metric-pill"><span class="metric-pill-icon" aria-hidden="true"><svg viewBox="0 0 16 16" role="img" aria-hidden="true"><rect x="2.5" y="3.2" width="11" height="10.3" rx="1.6"></rect><path d="M2.5 6.2h11"></path><path d="M5 1.8v2.6"></path><path d="M11 1.8v2.6"></path></svg></span><span class="metric-pill-text">{{ month_short }}</span></span>
      <div class="metric-track-wrap">
        <div class="metric-track" data-fill="{{ month_progress }}">
          <span class="metric-fill"></span>
        </div>
      </div>
      <span class="metric-value" aria-label="Month progress {{ month_progress }} percent"><span class="dot-text" data-dot-text="{{ month_progress }}" data-dot-scale="{{ metric_dot_scale }}" aria-label="{{ month_progress }}">{{ month_progress }}</span><span class="metric-unit">%</span></span>
    </div>

    <div class="metric-row">
      <span class="metric-pill"><span class="metric-pill-icon" aria-hidden="true"><svg viewBox="0 0 16 16" role="img" aria-hidden="true"><circle cx="8" cy="8" r="5.5"></circle><path d="M8 4.8v3.4l2.4 1.4"></path></svg></span><span class="metric-pill-text">{{ year_text }}</span></span>
      <div class="metric-track-wrap">
        <div class="metric-track" data-fill="{{ year_progress }}">
          <span class="metric-fill"></span>
        </div>
      </div>
      <span class="metric-value" aria-label="Year progress {{ year_progress }} percent"><span class="dot-text" data-dot-text="{{ year_progress }}" data-dot-scale="{{ metric_dot_scale }}" aria-label="{{ year_progress }}">{{ year_progress }}</span><span class="metric-unit">%</span></span>
    </div>
    {% if custom_has_target %}
    <div class="metric-row">
      <span class="metric-pill"><span class="metric-pill-icon" aria-hidden="true"><svg viewBox="0 0 16 16" role="img" aria-hidden="true"><circle cx="8" cy="8" r="5.5"></circle><circle cx="8" cy="8" r="2.2"></circle><path d="M8 1.8v2"></path><path d="M8 12.2v2"></path><path d="M1.8 8h2"></path><path d="M12.2 8h2"></path></svg></span><span class="metric-pill-text">{{ custom_target_label }}</span></span>
      <div class="metric-track-wrap">
        <div class="metric-track" data-fill="{{ custom_progress }}">
          <span class="metric-fill"></span>
        </div>
      </div>
      <span class="metric-value" aria-label="{{ custom_target_label }} countdown {{ custom_days_until }} days"><span class="dot-text" data-dot-text="{{ custom_days_until }}" data-dot-scale="{{ metric_dot_scale }}" aria-label="{{ custom_days_until }}">{{ custom_days_until }}</span><span class="metric-unit">D</span></span>
