      <span class="next-holiday-icon" aria-hidden="true">
        <svg viewBox="0 0 16 16" role="img" aria-hidden="true"><path d="M3 1.5v13"></path><path d="M3.8 2.6h8l-1.4 2.2 1.4 2.2h-8z"></path></svg>
