  {% else %}
  <section class="panel metrics-panel">
    <p class="no-data">NO DATA</p>
  </section>
  {% endif %}
</div>

<script>
(() => {
  const shell = document.querySelector('.today-shell.mode-quadrant');
  const FORCE_LIGHT_MODE_RAW = {{ trmnl.plugin_settings.custom_fields_values.force_light_mode | default: force_light_mode | default: "false" | json }};
  const FORCE_LIGHT_MODE = /^(1|true|yes|on)$/i.test(String(FORCE_LIGHT_MODE_RAW));

  const applyModeTone = () => {
    if (!shell) {
      return;
    }
    if (FORCE_LIGHT_MODE) {
      shell.classList.add('is-mode-light', 'is-force-light');
      return;
    }
    shell.classList.remove('is-mode-light', 'is-force-light');
  };

  applyModeTone();

  if (shell) {
    const detectFromDocument = (doc) => {
      const selects = Array.from(doc.querySelectorAll('select'));
      const modelSelect = selects.find((select) => {
        const options = Array.from(select.options || []);
        return options.some((option) => /TRMNL/i.test(option.textContent || ''));
      });
      if (!modelSelect) {
        return null;
      }

      const selectedOption = modelSelect.options[modelSelect.selectedIndex];
      const text = String((selectedOption && selectedOption.textContent) || modelSelect.value || '').toUpperCase();
      if (text.includes('OG')) {
        return true;
      }
      if (text.includes('TRMNL X') || text.endsWith(' X')) {
        return false;
      }
      return null;
    };

    const applyPreviewModelOverride = () => {
      let previewIsOg = detectFromDocument(document);
      if (previewIsOg === null && window.parent && window.parent !== window) {
        try {
          previewIsOg = detectFromDocument(window.parent.document);
        } catch (error) {
          // Ignore cross-origin failures.
        }
      }
      if (previewIsOg !== null) {
        shell.classList.toggle('is-og', previewIsOg);
      }
    };

    applyPreviewModelOverride();
    document.addEventListener('change', applyPreviewModelOverride, true);
    if (window.parent && window.parent !== window) {
      try {
        window.parent.document.addEventListener('change', applyPreviewModelOverride, true);
      } catch (error) {
        // Ignore cross-origin failures.
      }
    }
  }

  const glyphs = {
    '0': ['01110', '10001', '10001', '10001', '10001', '10001', '01110'],
    '1': ['00100', '01100', '10100', '00100', '00100', '00100', '11110'],
    '2': ['11111', '00001', '00001', '01111', '10000', '10000', '11111'],
    '3': ['11111', '00001', '00001', '01110', '00001', '00001', '11110'],
    '4': ['10001', '10001', '10001', '11111', '00001', '00001', '00001'],
    '5': ['11111', '10000', '10000', '11110', '00001', '00001', '11110'],
    '6': ['01110', '10000', '10000', '11110', '10001', '10001', '01110'],
    '7': ['11111', '00001', '00010', '00100', '01000', '01000', '01000'],
    '8': ['01110', '10001', '10001', '01110', '10001', '10001', '01110'],
    '9': ['01110', '10001', '10001', '01111', '00001', '00001', '01110'],
    '+': ['00100', '00100', '11111', '00100', '00100', '00000', '00000'],
    '-': ['00000', '00000', '11111', '00000', '00000', '00000', '00000'],
    '.': ['00000', '00000', '00000', '00000', '00000', '00100', '00000'],
    ':': ['00000', '00100', '00100', '00000', '00000', '00100', '00100'],
    '%': ['10001', '10010', '00010', '00100', '01000', '10010', '10001'],
    ' ': ['00000', '00000', '00000', '00000', '00000', '00000', '00000']
  };

  const renderNode = (node) => {
    const text = String(node.dataset.dotText || '').toUpperCase();
    if (!text) {
      return;
    }

    const scale = parseFloat(node.dataset.dotScale);
    const cell = Number.isFinite(scale) && scale > 0 ? scale : 1.4;
    const columns = 6;
    const rows = 7;
    const spacing = 1;
    const svgWidth = (text.length * columns - spacing) * cell;
    const svgHeight = rows * cell;

    const ns = 'http://www.w3.org/2000/svg';
    const svg = document.createElementNS(ns, 'svg');
    svg.setAttribute('viewBox', `0 0 ${svgWidth} ${svgHeight}`);
    svg.setAttribute('width', `${svgWidth}`);
    svg.setAttribute('height', `${svgHeight}`);
    svg.setAttribute('aria-hidden', 'true');
    svg.setAttribute('class', 'dot-matrix-glyph');

    const onRadius = Math.max(0.8, cell * 0.44);
    const offRadius = Math.max(0.34, cell * 0.19);

    for (let i = 0; i < text.length; i++) {
      const glyph = glyphs[text[i]] || glyphs[' '];

      for (let row = 0; row < rows; row++) {
        const line = glyph[row] || '00000';
        for (let col = 0; col < 5; col++) {
          const bit = line[col] === '1';
          const dot = document.createElementNS(ns, 'circle');
          dot.setAttribute('cx', `${(i * columns + col + 0.5) * cell}`);
          dot.setAttribute('cy', `${(row + 0.5) * cell}`);
          dot.setAttribute('r', `${bit ? onRadius : offRadius}`);
          dot.setAttribute('class', bit ? 'dot-on' : 'dot-off');
          svg.appendChild(dot);
        }
      }
    }

    node.textContent = '';
    node.appendChild(svg);
  };

  document.querySelectorAll('.dot-text').forEach(renderNode);

  document.querySelectorAll('.metric-track[data-fill]').forEach((track) => {
    const raw = parseFloat(track.dataset.fill || '0');
    const bounded = Number.isFinite(raw) ? Math.max(0, Math.min(100, raw)) : 0;
    track.style.setProperty('--fill', bounded + '%');
  });
})();
</script>
