          {% elsif h_condition contains "mostly cloudy" %}{% assign h_icon = "wi-day-cloudy" %}
          {% elsif h_condition contains "partly cloudy" or h_condition contains "few" %}{% assign h_icon = "wi-day-cloudy" %}
          {% elsif h_condition contains "cloud" %}{% assign h_icon = "wi-cloudy" %}
          {% elsif h_condition contains "rain" or h_condition contains "shower" %}{% assign h_icon = "wi-day-rain" %}
          {% elsif h_condition contains "thunder" or h_condition contains "storm" %}{% assign h_icon = "wi-day-thunderstorm" %}
          {% elsif h_condition contains "snow" %}{% assign h_icon = "wi-day-snow" %}
          {% elsif h_condition contains "mist" or h_condition contains "fog" %}{% assign h_icon = "wi-day-fog" %}
          {% elsif h_condition contains "wind" %}{% assign h_icon = "wi-strong-wind" %}
          {% endif %}
        {% else %}
          {% assign h_icon = "wi-night-clear" %}
