          {% elsif h_condition contains "mostly cloudy" %}{% assign h_icon = "wi-night-alt-cloudy" %}
          {% elsif h_condition contains "partly cloudy" or h_condition contains "few" %}{% assign h_icon = "wi-night-alt-cloudy" %}
          {% elsif h_condition contains "cloud" %}{% assign h_icon = "wi-cloudy" %}
          {% elsif h_condition contains "rain" or h_condition contains "shower" %}{% assign h_icon = "wi-night-alt-rain" %}
          {% elsif h_condition contains "thunder" or h_condition contains "storm" %}{% assign h_icon = "wi-night-alt-thunderstorm" %}
          {% elsif h_condition contains "snow" %}{% assign h_icon = "wi-night-alt-snow" %}
