          <span class="label label--small lg:label--base flex flex--center-x flex--baseline"><span class="wind-direction" style="transform: rotate({{ wind_degrees }}deg);"><i class="wi wi-direction-up wi-sz-tiny inline middle"></i></span>{{ h.wind.speed }}</span>
        </div>
      </div>
      {% endfor %}
    </div>

  </div>

</div>

<div class="title_bar">
  <span class="title">Weather</span>
  <span class="instance">{{ location.city }}</span>
</div>

<script type="text/javascript">
  document.addEventListener("DOMContentLoaded", function() {
    var temps = "{{ temps }}".split(",").map(function(v) { return parseFloat(v); });
    var min = Math.min.apply(null, temps); var max = Math.max.apply(null, temps); var range = max - min || 1;
    var W = 400, H = 14, step = W / (temps.length - 1), path = "";
