{% assign d = range | default: 365 | plus: 10 %}{% assign secs = d | times: 86400 %}https://api.nasdaq.com/api/quote/{{ symbol | default: "GOOG" | upcase | strip }}/historical?assetclass=stocks&fromdate={{ "now" | date: "%s" | minus: secs | date: "%Y-%m-%d" }}&todate={{ "now" | date: "%Y-%m-%d" }}&limit=255
{% assign d = range | default: 365 | plus: 10 %}{% assign secs = d | times: 86400 %}https://api.nasdaq.com/api/quote/SPY/historical?assetclass=etf&fromdate={{ "now" | date: "%s" | minus: secs | date: "%Y-%m-%d" }}&todate={{ "now" | date: "%Y-%m-%d" }}&limit=255","polling_headers":"accept=application/json&user-agent=Mozilla/5.0 (compatible; GarageScreen/1.0)","custom_fields":[{"keyname":"about","field_type":"author_bio","name":"About This Plugin","description":"Shows GOOG price, 52-week high range, and a comparative performance chart against the S&P 500 index (SPY)."},{"keyname":"symbol","field_type":"string","name":"Stock Symbol","default":"GOOG"},{"keyname":"range","field_type":"select","name":"Time Range","options":[{"1 Year (52 Weeks)":"365"},{"6 Months":"180"},{"3 Months":"90"}],"default":"365"}]},"templates":{"shared":"{% assign q = IDX_0.data %}
{% assign sym = symbol | default: "GOOG" | upcase | strip %}
{% assign day_change = q.primaryData.netChange | remove: "," | plus: 0 %}

{% assign goog_rows = IDX_1.data.tradesTable.rows | reverse %}
{% assign spy_rows = IDX_2.data.tradesTable.rows | reverse %}

{% assign num_pts = goog_rows.size %}
{% if spy_rows.size < num_pts %}
  {% assign num_pts = spy_rows.size %}
{% endif %}

{% assign goog_price = q.primaryData.lastSalePrice | remove: "$" | remove: "," | plus: 0 %}

{% assign range_parts = q.keyStats.fiftyTwoWeekHighLow.value | split: " - " %}
{% assign w52_low = range_parts[0] | strip | remove: "$" | remove: "," | plus: 0 %}
{% assign w52_high = range_parts[1] | strip | remove: "$" | remove: "," | plus: 0 %}

{% if w52_high == 0 or w52_high == nil %}
  {% assign w52_high = goog_price %}
  {% for r in goog_rows %}
    {% assign c = r.close | remove: "$" | remove: "," | plus: 0 %}
    {% if c > w52_high %}{% assign w52_high = c %}{% endif %}
  {% endfor %}
{% endif %}

{% if w52_low == 0 or w52_low == nil %}
  {% assign w52_low = goog_price %}
  {% for r in goog_rows %}
    {% assign c = r.close | remove: "$" | remove: "," | plus: 0 %}
    {% if c < w52_low %}{% assign w52_low = c %}{% endif %}
  {% endfor %}
{% endif %}

{% assign diff_from_high = goog_price | minus: w52_high %}
{% assign diff_dollars_from_high = w52_high | minus: goog_price | round: 2 %}
{% assign pct_from_high = diff_from_high | times: 100.0 | divided_by: w52_high | round: 1 %}

{% assign w52_span = w52_high | minus: w52_low %}
{% if w52_span > 0 %}
  {% assign w52_pos = goog_price | minus: w52_low | times: 100.0 | divided_by: w52_span | round: 0 %}
  {% if w52_pos > 100 %}{% assign w52_pos = 100 %}{% endif %}
  {% if w52_pos < 0 %}{% assign w52_pos = 0 %}{% endif %}
{% else %}
  {% assign w52_pos = 50 %}
{% endif %}

{% assign goog_start = goog_rows.first.close | remove: "$" | remove: "," | plus: 0 %}
{% assign goog_end = goog_rows.last.close | remove: "$" | remove: "," | plus: 0 %}
{% assign goog_total_ret = goog_end | minus: goog_start | times: 100.0 | divided_by: goog_start | round: 1 %}

{% assign spy_start = spy_rows.first.close | remove: "$" | remove: "," | plus: 0 %}
{% assign spy_end = spy_rows.last.close | remove: "$" | remove: "," | plus: 0 %}
{% assign spy_total_ret = spy_end | minus: spy_start | times: 100.0 | divided_by: spy_start | round: 1 %}

{% assign alpha = goog_total_ret | minus: spy_total_ret | round: 1 %}

{% assign start_date = goog_rows.first.date %}
{% assign end_date = goog_rows.last.date %}

{% comment %} Calculate min_ret and max_ret across both series in shared {% endcomment %}
{% assign min_ret = 0.0 %}
{% assign max_ret = 0.0 %}

{% for r in goog_rows %}
  {% assign c = r.close | remove: "$" | remove: "," | plus: 0 %}
  {% assign ret = c | minus: goog_start | times: 100.0 | divided_by: goog_start %}
  {% if ret < min_ret %}{% assign min_ret = ret %}{% endif %}
  {% if ret > max_ret %}{% assign max_ret = ret %}{% endif %}
  {% if forloop.index >= num_pts %}{% break %}{% endif %}
{% endfor %}

{% for r in spy_rows %}
  {% assign c = r.close | remove: "$" | remove: "," | plus: 0 %}
  {% assign ret = c | minus: spy_start | times: 100.0 | divided_by: spy_start %}
  {% if ret < min_ret %}{% assign min_ret = ret %}{% endif %}
  {% if ret > max_ret %}{% assign max_ret = ret %}{% endif %}
  {% if forloop.index >= num_pts %}{% break %}{% endif %}
{% endfor %}

{% assign pad = max_ret | minus: min_ret | times: 0.08 %}
{% if pad < 1.0 %}{% assign pad = 1.0 %}{% endif %}
{% assign chart_min = min_ret | minus: pad %}
{% assign chart_max = max_ret | plus: pad %}
{% assign chart_span = chart_max | minus: chart_min %}
{% if chart_span <= 0 %}{% assign chart_span = 1.0 %}{% endif %}

{% template comparison_chart %}
  {% assign n_dec = num_pts | minus: 1 %}
  {% if n_dec < 1 %}{% assign n_dec = 1 %}{% endif %}

  {% capture goog_pts %}
    {% for r in goog_rows %}
      {% assign c = r.close | remove: "$" | remove: "," | plus: 0 %}
      {% assign ret = c | minus: goog_start | times: 100.0 | divided_by: goog_start %}
      {% assign x = forloop.index0 | times: cw | divided_by: n_dec | round: 1 %}
      {% assign y = chart_max | minus: ret | times: h | divided_by: chart_span | round: 1 %}
      {{ x }},{{ y }}
      {% if forloop.index >= num_pts %}{% break %}{% endif %}
    {% endfor %}
  {% endcapture %}

  {% capture spy_pts %}
    {% for r in spy_rows %}
      {% assign c = r.close | remove: "$" | remove: "," | plus: 0 %}
      {% assign ret = c | minus: spy_start | times: 100.0 | divided_by: spy_start %}
      {% assign x = forloop.index0 | times: cw | divided_by: n_dec | round: 1 %}
      {% assign y = chart_max | minus: ret | times: h | divided_by: chart_span | round: 1 %}
      {{ x }},{{ y }}
      {% if forloop.index >= num_pts %}{% break %}{% endif %}
    {% endfor %}
  {% endcapture %}

  {% assign zero_y = chart_max | minus: 0.0 | times: h | divided_by: chart_span | round: 1 %}

  {% assign last_goog_ret = goog_total_ret %}
  {% assign last_goog_y = chart_max | minus: last_goog_ret | times: h | divided_by: chart_span | round: 1 %}
  {% assign last_spy_ret = spy_total_ret %}
  {% assign last_spy_y = chart_max | minus: last_spy_ret | times: h | divided_by: chart_span | round: 1 %}

  {% assign axis_x = cw | plus: 6 %}

