    <!-- Top & Bottom bounds labels on right axis -->
    <text x="{{ axis_x }}" y="12" font-size="11" font-weight="bold" fill="#000">+{{ chart_max | round: 0 }}%</text>
    <text x="{{ axis_x }}" y="{{ h | minus: 4 }}" font-size="11" font-weight="bold" fill="#000">{% if chart_min > 0 %}+{% endif %}{{ chart_min | round: 0 }}%</text>

