    <!-- End point markers -->
    <circle cx="{{ cw }}" cy="{{ last_spy_y }}" r="4" fill="#fff" stroke="#000" stroke-width="2" />
    <circle cx="{{ cw }}" cy="{{ last_goog_y }}" r="5" fill="#000" />
  </svg>
{% endtemplate %}
","full":"<div class="layout layout--col" style="gap:8px;padding:8px 16px 0;justify-content:flex-start">

  <!-- Top Row: Price & 52-Week High -->
  <div class="flex flex--row stretch-x" style="align-items:flex-start">
