strategy: polling
framework_version: 3.2.0
polling_verb: get
polling_url: |-
  https://api.nasdaq.com/api/quote/{{ symbol | default: "GOOG" | upcase | strip }}/info?assetclass=stocks
  {% assign d = range | default: 365 | plus: 10 %}{% assign secs = d | times: 86400 %}https://api.nasdaq.com/api/quote/{{ symbol | default: "GOOG" | upcase | strip }}/historical?assetclass=stocks&fromdate={{ "now" | date: "%s" | minus: secs | date: "%Y-%m-%d" }}&todate={{ "now" | date: "%Y-%m-%d" }}&limit=255
  {% assign d = range | default: 365 | plus: 10 %}{% assign secs = d | times: 86400 %}https://api.nasdaq.com/api/quote/SPY/historical?assetclass=etf&fromdate={{ "now" | date: "%s" | minus: secs | date: "%Y-%m-%d" }}&todate={{ "now" | date: "%Y-%m-%d" }}&limit=255
polling_headers: accept=application/json&user-agent=Mozilla/5.0 (compatible; GarageScreen/1.0)
custom_fields:
- keyname: about
  field_type: author_bio
  name: About This Plugin
  description: Shows GOOG price, 52-week high range, and a comparative performance chart against the S&P 500 index (SPY).
- keyname: symbol
  field_type: string
  name: Stock Symbol
  default: GOOG
- keyname: range
  field_type: select
  name: Time Range
  options:
  - 1 Year (52 Weeks): '365'
  - 6 Months: '180'
  - 3 Months: '90'
  default: '365'
