        <div style="border-left:3px solid #000;padding-left:14px">
          <span class="label label--small label--inverted" style="padding:2px 8px;font-weight:800">LIVE · {{ live_period_label }}{% if live_game.clock.timeRemaining %} · {{ live_game.clock.timeRemaining }}{% endif %}</span>
          <div class="flex flex--row" style="align-items:baseline;gap:8px;margin-top:4px">
            <span class="value value--tnums" style="font-size:40px;line-height:1;font-weight:800">{{ live_us.score | default: 0 }}–{{ live_them.score | default: 0 }}</span>
            <span style="font-size:18px;font-weight:700">{{ live_where }} {{ live_them.commonName.default }}</span>
          </div>
        </div>
      {% endif %}
    </div>
    {% if has_me %}
    <div class="text--right">
      <span class="value value--tnums" style="font-size:38px;line-height:1">{{ record }}</span>
      <div class="label label--small" style="display:block;margin-top:6px">{{ me.points }} pts · {{ me.divisionSequence | ordinalize }} in {{ me.divisionName }} · {{ me.streakCode }}{{ me.streakCount }}</div>
    </div>
    {% endif %}
  </div>

  <!-- Mid Section: Last Game (Left) & Next 5 Games Stacked Grid (Right) -->
  <div class="flex flex--row stretch-x" style="align-items:stretch;border-bottom:3px solid #000;padding:8px 0;min-height:148px">
    <!-- Last Game -->
    <div style="width:220px;flex-shrink:0;padding-right:16px;border-right:3px solid #000;display:flex;flex-direction:column;justify-content:center">
      <span class="label label--small" style="margin-bottom:4px">Last game</span>
      {% if has_prev %}
      <div class="flex flex--row" style="align-items:center;gap:10px">
        <span style="background:#000;color:#fff;font-weight:800;font-size:20px;line-height:1;padding:3px 7px">{{ p_result }}</span>
        <span class="value value--tnums" style="font-size:36px;line-height:.9">{{ p_us.score }}–{{ p_them.score }}</span>
      </div>
      <div style="margin-top:6px;font-size:15px;line-height:1.2;font-weight:600">
        {{ p_loc_label }} <b>{{ p_them.commonName.default }}</b><br>
        <span class="value--tnums" style="font-size:14px;font-weight:500">{{ p_day }}{% if p_type != "REG" %} · {{ p_type }}{% endif %}</span>
      </div>
      {% else %}
      <div class="description">No recent games.</div>
      {% endif %}
    </div>

    <!-- Next 5 Games Grid: Meticulously aligned rows -->
    <div style="flex:1;min-width:0;padding-left:16px;display:flex;flex-direction:column;justify-content:space-between">
      <div class="flex flex--row flex--between" style="align-items:center;margin-bottom:3px">
        <span class="label label--small">Upcoming Schedule (Next 5)</span>
        <span class="label label--small" style="font-size:11px">* Next home game</span>
      </div>
      {% for row in upcoming_list limit:5 %}
        <div class="flex flex--row" style="align-items:center;height:24px;border-bottom:1px dotted #ccc;{% if row.is_next_home %}background:#000;color:#fff;padding:0 6px;margin:0 -6px{% endif %}">
          <!-- Location tag: 'in City' or 'vs' left-aligned -->
          <div style="width:90px;font-size:14px;font-weight:700;white-space:nowrap;overflow:hidden;text-overflow:ellipsis">
            {{ row.where }}
          </div>
          <!-- Opponent Logo (prominent size) -->
          <div style="width:32px;display:flex;align-items:center;justify-content:center">
            {% if row.them.logo %}
              <img src="{{ row.them.logo }}" style="width:24px;height:24px;object-fit:contain;filter:grayscale(100%) contrast(200%);image-rendering:pixelated;{% if row.is_next_home %}filter:invert(100%){% endif %}" alt="{{ row.them.commonName.default }}">
            {% endif %}
          </div>
          <!-- Opponent Name -->
          <div style="width:110px;font-size:14px;font-weight:800;white-space:nowrap;overflow:hidden;text-overflow:ellipsis;margin-left:6px">
            {{ row.them.commonName.default }}
          </div>
          <!-- Day left-aligned in column -->
          <div style="width:100px;font-size:14px;font-weight:700;white-space:nowrap" class="value--tnums">
            {{ row.day }}
          </div>
          <!-- Time / Start aligned right -->
          <div style="flex:1;text-align:right;font-size:14px;font-weight:700;white-space:nowrap" class="value--tnums">
            {{ row.time }}
          </div>
        </div>
      {% endfor %}
    </div>
  </div>

  <!-- Standings Bar Chart -->
  {% if has_me %}
  <div style="padding-top:6px">
    <div class="flex flex--row stretch-x" style="align-items:flex-end;justify-content:space-between;height:114px;padding:0 8px">
      {% for t in division limit:8 %}
        {% assign h = t.points | times: 78 | divided_by: max_pts %}
        {% if h < 6 %}{% assign h = 6 %}{% endif %}
        {% assign is_selected = false %}
        {% if t.teamAbbrev.default == team %}
          {% assign is_selected = true %}
        {% endif %}
        <div class="flex flex--col flex--center" style="width:74px;align-items:center;height:100%;justify-content:flex-end">
          <span class="value value--tnums" style="font-size:16px;font-weight:800;line-height:1;margin-bottom:3px;{% if is_selected %}background:#000;color:#fff;padding:1px 4px{% endif %}">{{ t.points }}</span>
          {% if forloop.index <= 2 %}
            <div style="width:44px;height:{{ h }}px;background:#000"></div>
          {% elsif forloop.index == 3 %}
            <svg width="44" height="{{ h }}" style="display:block">
              <rect width="44" height="{{ h }}" fill="url(#crosshatch)" stroke="#000" stroke-width="2" />
            </svg>
          {% else %}
            <div style="box-sizing:border-box;width:44px;height:{{ h }}px;background:#fff;border:2px solid #000"></div>
          {% endif %}
          <div style="margin-top:4px;text-align:center;line-height:1">
            <div style="font-size:14px;font-weight:800;letter-spacing:-0.5px;{% if is_selected %}text-decoration:underline;text-decoration-thickness:2px{% endif %}">{{ t.teamAbbrev.default }}</div>
          </div>
        </div>
      {% endfor %}
    </div>
  </div>
  {% endif %}
</div>

<div class="title_bar">
  <span class="title">{{ nickname }}</span>
  <span class="instance">NHL · Standings as of {{ as_of }}</span>
</div>","half_vertical.liquid":"<div class="layout layout--col" style="font-family:var(--value-font-family);gap:0;padding:6px 10px 0;height:434px;justify-content:space-between;align-items:stretch">
