      <div class="flex flex--row" style="align-items:center;gap:6px">
        <span style="background:#000;color:#fff;font-weight:800;font-size:14px;line-height:1;padding:2px 4px">{{ p_result }}</span>
        <span class="value value--tnums" style="font-size:22px;line-height:1">{{ p_us.score }}–{{ p_them.score }}</span>
