<div class="layout layout--col" style="font-family:var(--value-font-family);gap:0;padding:2px 16px 0;height:440px;justify-content:space-between;align-items:stretch">
  <!-- Header: Huge team logo, minimal padding, record & live score -->
  <div class="flex flex--row flex--between stretch-x" style="align-items:center;padding-bottom:3px;border-bottom:3px solid #000">
    <div class="flex flex--row" style="align-items:center;gap:16px">
      {% if logo_url %}
        <img src="{{ logo_url }}" style="width:130px;height:120px;object-fit:contain;filter:grayscale(100%) contrast(1000%);image-rendering:pixelated" alt="{{ team }}">
      {% endif %}
      {% if live_game %}
        <div style="border-left:3px solid #000;padding-left:14px">
          <span class="label label--small label--inverted" style="padding:2px 8px;font-weight:800">LIVE · {{ live_period_label }}{% if live_game.clock.timeRemaining %} · {{ live_game.clock.timeRemaining }}{% endif %}</span>
