      </div>
      {% else %}
      <div class="description" style="text-align:left">No recent games.</div>
      {% endif %}
    </div>

    <!-- Upcoming 4 Games Grid: scaled up logos, increased row height -->
    <div style="flex:1;min-width:0;padding-left:18px;display:flex;flex-direction:column;justify-content:space-between">
      <div class="flex flex--row flex--between" style="align-items:center;margin-bottom:2px">
        <span class="label label--small" style="letter-spacing:1px">UPCOMING</span>
