      {% for row in upcoming_list limit:4 %}
        <div class="flex flex--row" style="align-items:center;height:38px;border-bottom:1px solid #000;{% if row.is_next_home %}outline:2px solid #000;outline-offset:1px;padding:0 6px;margin:0 -6px;background:rgba(0,0,0,0.03);{% endif %}">
          <!-- Col 1: Significantly larger opponent logo -->
          <div style="width:48px;height:36px;flex-shrink:0;display:flex;align-items:center;justify-content:center">
            {% if row.them.logo %}
              <img src="{{ row.them.logo }}" style="width:44px;height:34px;object-fit:contain;filter:grayscale(100%) contrast(1000%);image-rendering:pixelated" alt="{{ row.them.commonName.default }}">
            {% endif %}
          </div>
          <!-- Col 2: 'at' or 'vs' -->
          <div style="width:38px;padding-left:8px;font-size:16px;font-weight:800;white-space:nowrap">
            {{ row.where }}
          </div>
          <!-- Col 3: Opponent Name -->
          <div style="width:130px;font-size:16px;font-weight:800;white-space:nowrap;overflow:hidden;text-overflow:ellipsis">
            {{ row.them.commonName.default }}
          </div>
          <!-- Col 4: Day -->
          <div style="width:115px;font-size:16px;font-weight:700;white-space:nowrap" class="value--tnums">
            {{ row.day }}
          </div>
          <!-- Col 5: Time -->
          <div style="flex:1;text-align:right;font-size:16px;font-weight:800;white-space:nowrap" class="value--tnums">
            {{ row.time }}
          </div>
        </div>
      {% endfor %}
    </div>
  </div>

  <!-- Compact Standings Bar Chart -->
  {% if has_me %}
  <div style="padding-top:4px">
    <div class="flex flex--row stretch-x" style="align-items:flex-end;justify-content:space-between;height:88px;padding:0 8px">
      {% for t in division limit:8 %}
        {% assign h = t.points | times: 54 | divided_by: max_pts %}
        {% if h < 6 %}{% assign h = 6 %}{% endif %}
        {% assign is_selected = false %}
        {% if t.teamAbbrev.default == team %}
          {% assign is_selected = true %}
        {% endif %}
        <div class="flex flex--col flex--center" style="width:74px;align-items:center;height:100%;justify-content:flex-end">
          <span class="value value--tnums" style="font-size:15px;font-weight:800;line-height:1;margin-bottom:2px;{% if is_selected %}background:#000;color:#fff;padding:1px 4px{% endif %}">{{ t.points }}</span>
          {% if forloop.index <= 2 %}
            <div style="width:44px;height:{{ h }}px;background:#000"></div>
          {% elsif forloop.index == 3 %}
            <svg width="44" height="{{ h }}" style="display:block">
              <rect width="44" height="{{ h }}" fill="url(#crosshatch)" stroke="#000" stroke-width="2" />
            </svg>
          {% else %}
            <div style="box-sizing:border-box;width:44px;height:{{ h }}px;background:#fff;border:2px solid #000"></div>
          {% endif %}
          <div style="margin-top:3px;text-align:center;line-height:1">
            <div style="font-size:13px;font-weight:800;letter-spacing:-0.5px;{% if is_selected %}text-decoration:underline;text-decoration-thickness:2px{% endif %}">{{ t.teamAbbrev.default }}</div>
          </div>
        </div>
      {% endfor %}
    </div>
  </div>
  {% endif %}
</div>

<div class="title_bar">
  <span class="title">{{ nickname }}</span>
  <span class="instance">NHL · Standings as of {{ as_of }}</span>
</div>","half_vertical.liquid":"<div class="layout layout--col" style="font-family:var(--value-font-family);gap:0;padding:4px 10px 0;height:436px;justify-content:space-between;align-items:stretch">
