    </pattern>
  </defs>
</svg>

<div class="layout layout--col" style="font-family:var(--value-font-family);gap:0;padding:2px 16px 0;height:436px;justify-content:space-between;align-items:stretch">
  <!-- Header: Huge Team Logo + Live Game (if on) + Season Record -->
  <div class="flex flex--row flex--between stretch-x" style="align-items:center;padding:0 0 2px;border-bottom:3px solid #000">
    <div class="flex flex--row" style="align-items:center;gap:16px">
      {% if logo_url %}
        <img src="{{ logo_url }}" style="width:105px;height:105px;object-fit:contain;filter:grayscale(100%) contrast(1000%);image-rendering:pixelated" alt="{{ team }}">
      {% endif %}
      {% if live_game %}
        <div style="border-left:3px solid #000;padding-left:12px">
          <span class="label label--small label--inverted" style="padding:2px 8px;font-weight:800">LIVE · {{ live_period_label }}{% if live_game.clock.timeRemaining %} · {{ live_game.clock.timeRemaining }}{% endif %}</span>
          <div class="flex flex--row" style="align-items:baseline;gap:8px;margin-top:2px">
            <span class="value value--tnums" style="font-size:38px;line-height:1;font-weight:800">{{ live_us.score | default: 0 }}–{{ live_them.score | default: 0 }}</span>
            <span style="font-size:18px;font-weight:500">{{ live_where }} {{ live_them.commonName.default }}</span>
          </div>
        </div>
      {% endif %}
    </div>
    {% if has_me %}
    <div class="text--right">
      <span class="value value--tnums" style="font-size:38px;line-height:1">{{ record }}</span>
      <div class="label label--small" style="display:block;margin-top:2px">{{ me.points }} pts · {{ me.divisionSequence | ordinalize }} in {{ me.divisionName }} · {{ me.streakCode }}{{ me.streakCount }}</div>
    </div>
    {% endif %}
  </div>

  <!-- Mid Section: Last Game 1/3 + Upcoming 2/3 -->
  <div class="flex flex--row stretch-x" style="align-items:stretch;border-bottom:3px solid #000;padding:6px 0;flex:1">
    <!-- Last Game -->
    <div style="width:220px;flex-shrink:0;padding-right:16px;border-right:3px solid #000;display:flex;flex-direction:column;justify-content:center;text-align:left">
      <span class="label label--small" style="margin-bottom:6px;text-align:left">Last game</span>
      {% if has_prev %}
      <div class="flex flex--row" style="align-items:center;gap:10px;justify-content:flex-start">
        <span style="background:#000;color:#fff;font-weight:800;font-size:22px;line-height:1;padding:4px 8px">{{ p_result }}</span>
        <span class="value value--tnums" style="font-size:42px;line-height:.9;font-weight:800">{{ p_us.score }}–{{ p_them.score }}</span>
      </div>
      <div style="margin-top:8px;font-size:18px;line-height:1.2;text-align:left">
        {{ p_loc_label }} <span style="font-weight:500">{{ p_them.commonName.default }}</span><br>
        <span class="value--tnums" style="font-size:15px;font-weight:600">{{ p_day }}{% if p_type != "REG" %} · {{ p_type }}{% endif %}</span>
      </div>
      {% else %}
      <div class="description" style="text-align:left">No recent games.</div>
      {% endif %}
    </div>

    <!-- Next Games Grid: Col 1 is 'at'/'vs', Col 2 is Opponent Logo right next to name, unbolded team text, subtle grey for next home game -->
    <div style="flex:1;min-width:0;padding-left:16px;display:flex;flex-direction:column;justify-content:space-between">
      <div class="flex flex--row flex--between" style="align-items:center;margin-bottom:2px">
        <span class="label label--small">Upcoming</span>
      </div>
      {% for row in upcoming_list limit:4 %}
        <div class="flex flex--row" style="align-items:center;height:38px;border-bottom:1px dotted #ccc;padding:0 4px;{% if row.is_next_home %}background:#e5e5e5;{% endif %}">
          <!-- Col 1: 'at' or 'vs' -->
          <div style="width:32px;font-size:16px;font-weight:700;white-space:nowrap">
            {{ row.where }}
          </div>
          <!-- Col 2: Even Bigger Opponent Logo right next to team name -->
          <div style="width:54px;flex-shrink:0;display:flex;align-items:center;justify-content:flex-start">
            {% if row.them.logo %}
              <img src="{{ row.them.logo }}" style="width:50px;height:36px;object-fit:contain;filter:grayscale(100%) contrast(1000%);image-rendering:pixelated" alt="{{ row.them.commonName.default }}">
            {% endif %}
          </div>
          <!-- Col 3: Opponent Name (not bold) -->
          <div style="width:150px;font-size:16px;font-weight:500;white-space:nowrap;overflow:hidden;text-overflow:ellipsis">
            {{ row.them.commonName.default }}
          </div>
          <!-- Col 4: Day -->
          <div style="width:105px;font-size:15px;font-weight:600;white-space:nowrap" class="value--tnums">
            {{ row.day }}
          </div>
          <!-- Col 5: Time -->
          <div style="flex:1;text-align:right;font-size:15px;font-weight:700;white-space:nowrap" class="value--tnums">
            {{ row.time }}
          </div>
        </div>
      {% endfor %}
    </div>
  </div>

  <!-- Standings Bar Chart -->
  {% if has_me %}
  <div style="padding-top:4px">
    <div class="flex flex--row stretch-x" style="align-items:flex-end;justify-content:space-between;height:98px;padding:0 8px">
      {% for t in division limit:8 %}
        {% assign h = t.points | times: 65 | divided_by: max_pts %}
        {% if h < 6 %}{% assign h = 6 %}{% endif %}
        {% assign is_selected = false %}
        {% if t.teamAbbrev.default == team %}
          {% assign is_selected = true %}
        {% endif %}
        <div class="flex flex--col flex--center" style="width:74px;align-items:center;height:100%;justify-content:flex-end">
          <span class="value value--tnums" style="font-size:15px;font-weight:800;line-height:1;margin-bottom:3px;{% if is_selected %}background:#000;color:#fff;padding:1px 4px{% endif %}">{{ t.points }}</span>
          {% if forloop.index <= 2 %}
            <div style="width:44px;height:{{ h }}px;background:#000"></div>
          {% elsif forloop.index == 3 %}
            <svg width="44" height="{{ h }}" style="display:block">
              <rect width="44" height="{{ h }}" fill="url(#crosshatch)" stroke="#000" stroke-width="2" />
            </svg>
          {% else %}
            <div style="box-sizing:border-box;width:44px;height:{{ h }}px;background:#fff;border:2px solid #000"></div>
          {% endif %}
          <div style="margin-top:3px;text-align:center;line-height:1">
            <div style="font-size:13px;font-weight:800;letter-spacing:-0.5px;{% if is_selected %}text-decoration:underline;text-decoration-thickness:2px{% endif %}">{{ t.teamAbbrev.default }}</div>
          </div>
        </div>
      {% endfor %}
    </div>
  </div>
  {% endif %}
</div>

<div class="title_bar">
  <span class="title">{{ nickname }}</span>
  <span class="instance">NHL · Standings as of {{ as_of }}</span>
</div>","half_vertical.liquid":"<div class="layout layout--col" style="font-family:var(--value-font-family);gap:0;padding:4px 10px 0;height:434px;justify-content:space-between;align-items:stretch">
