</div>","shared.liquid":"{% assign team = team | default: "SEA" | upcase | strip %}
{% assign off = trmnl.user.utc_offset | default: 0 %}
{% assign today = "now" | date: "%s" | plus: off | date: "%Y-%m-%d" %}
{% assign tomorrow = "now" | date: "%s" | plus: off | plus: 86400 | date: "%Y-%m-%d" %}
{% assign yesterday = "now" | date: "%s" | plus: off | minus: 86400 | date: "%Y-%m-%d" %}

{% assign has_prev = false %}
{% assign live_game = nil %}
{% assign logo_url = nil %}

{% assign upcoming_list = "" | split: "" %}
{% assign found_next_home = false %}

{% for day in IDX_0.gamesByDate %}
  {% for g in day.games %}
    {% if g.homeTeam.abbrev == team and logo_url == nil %}
      {% assign logo_url = g.homeTeam.logo %}
    {% elsif g.awayTeam.abbrev == team and logo_url == nil %}
      {% assign logo_url = g.awayTeam.logo %}
    {% endif %}

    {% if g.gameState == "LIVE" or g.gameState == "CRIT" %}
      {% assign live_game = g %}
    {% endif %}

    {% if g.gameState == "OFF" or g.gameState == "FINAL" %}
      {% assign prev_game = g %}
      {% assign has_prev = true %}
    {% elsif g.gameState == "FUT" or g.gameState == "PRE" or g.gameState == "LIVE" or g.gameState == "CRIT" %}
      {% assign is_home = false %}
      {% if g.homeTeam.abbrev == team %}
        {% assign is_home = true %}
        {% assign u_us = g.homeTeam %}
        {% assign u_them = g.awayTeam %}
        {% assign u_where = "vs" %}
      {% else %}
        {% assign u_us = g.awayTeam %}
        {% assign u_them = g.homeTeam %}
        {% assign u_where = "at" %}
      {% endif %}

      {% assign u_ts = g.startTimeUTC | date: "%s" %}
      {% assign u_local_ts = u_ts | plus: off %}
      {% assign u_date = u_local_ts | date: "%Y-%m-%d" %}
      {% if u_date == today %}
        {% assign u_day = "Today" %}
      {% elsif u_date == tomorrow %}
        {% assign u_day = "Tomorrow" %}
      {% else %}
        {% assign u_day = u_local_ts | date: "%a, %b %-d" %}
      {% endif %}
      {% assign u_time = u_local_ts | date: "%-I:%M %p" %}

      {% assign is_target_home = false %}
      {% if is_home and found_next_home == false %}
        {% assign is_target_home = true %}
        {% assign found_next_home = true %}
      {% endif %}

      {% capture item_json %}{"where": {{ u_where | json }}, "day": {{ u_day | json }}, "time": {{ u_time | json }}, "is_home": {{ is_home | json }}, "is_next_home": {{ is_target_home | json }}, "them": {"commonName": {"default": {{ u_them.commonName.default | json }}}, "logo": {{ u_them.logo | json }}}}{% endcapture %}
      {% assign parsed_item = item_json | parse_json %}
      {% assign upcoming_list = upcoming_list | push: parsed_item %}
    {% endif %}
  {% endfor %}
{% endfor %}

{% assign has_me = false %}
{% for t in IDX_1.standings %}
  {% if t.teamAbbrev.default == team %}
    {% assign me = t %}
    {% assign has_me = true %}
    {% if logo_url == nil %}
      {% assign logo_url = t.teamLogo %}
    {% endif %}
  {% endif %}
{% endfor %}

{% if logo_url == nil %}
  {% assign logo_url = "https://assets.nhle.com/logos/nhl/svg/" | append: team | append: "_light.svg" %}
{% endif %}

{% if live_game %}
  {% if live_game.homeTeam.abbrev == team %}
    {% assign live_us = live_game.homeTeam %}
    {% assign live_them = live_game.awayTeam %}
    {% assign live_where = "vs" %}
  {% else %}
    {% assign live_us = live_game.awayTeam %}
    {% assign live_them = live_game.homeTeam %}
    {% assign live_where = "at" %}
  {% endif %}
  {% assign live_period = live_game.periodDescriptor.number | default: 1 %}
  {% if live_game.periodDescriptor.periodType == "OT" %}
    {% assign live_period_label = "OT" %}
  {% elsif live_game.periodDescriptor.periodType == "SO" %}
    {% assign live_period_label = "SO" %}
  {% else %}
    {% assign live_period_label = live_period | ordinalize %}
  {% endif %}
{% endif %}

{% if has_prev %}
  {% if prev_game.homeTeam.abbrev == team %}
    {% assign p_us = prev_game.homeTeam %}
    {% assign p_them = prev_game.awayTeam %}
    {% assign p_loc_label = "vs" %}
  {% else %}
    {% assign p_us = prev_game.awayTeam %}
    {% assign p_them = prev_game.homeTeam %}
    {% assign p_loc_label = "at" %}
  {% endif %}
  {% assign p_type = prev_game.periodDescriptor.periodType | default: "REG" %}
  {% if p_us.score > p_them.score %}
    {% assign p_result = "W" %}
  {% elsif p_type == "REG" %}
    {% assign p_result = "L" %}
  {% else %}
    {% assign p_result = "OTL" %}
  {% endif %}
  {% assign p_date = prev_game.startTimeUTC | date: "%s" | plus: off | date: "%Y-%m-%d" %}
  {% if p_date == today %}
    {% assign p_day = "Today" %}
  {% elsif p_date == yesterday %}
    {% assign p_day = "Yesterday" %}
  {% else %}
    {% assign p_day = prev_game.startTimeUTC | date: "%s" | plus: off | date: "%a, %b %-d" %}
  {% endif %}
{% endif %}

{% if has_me %}
  {% assign division = IDX_1.standings | where: "divisionAbbrev", me.divisionAbbrev | sort: "divisionSequence" %}
  {% assign record = me.wins | append: "–" | append: me.losses | append: "–" | append: me.otLosses %}
  {% assign nickname = me.teamCommonName.default %}
  {% assign max_pts = 1 %}
  {% for d_team in division %}
    {% if d_team.points > max_pts %}
      {% assign max_pts = d_team.points %}
    {% endif %}
  {% endfor %}
{% else %}
  {% assign nickname = team %}
{% endif %}

{% assign as_of = IDX_1.standings.first.date | append: "T12:00:00" | date: "%b %-d" %}"}}

