","shared.liquid":"{% assign team = team | default: "SEA" | upcase | strip %}
{% assign off = trmnl.user.utc_offset | default: 0 %}
{% assign today = "now" | date: "%s" | plus: off | date: "%Y-%m-%d" %}
{% assign tomorrow = "now" | date: "%s" | plus: off | plus: 86400 | date: "%Y-%m-%d" %}
{% assign yesterday = "now" | date: "%s" | plus: off | minus: 86400 | date: "%Y-%m-%d" %}

{% assign has_prev = false %}
{% assign has_next = false %}
{% for day in IDX_0.gamesByDate %}
  {% for g in day.games %}
    {% if g.gameState == "OFF" or g.gameState == "FINAL" %}
      {% assign prev_game = g %}
      {% assign has_prev = true %}
    {% endif %}
    {% unless has_next %}
      {% if g.gameState == "LIVE" or g.gameState == "CRIT" or g.gameState == "FUT" or g.gameState == "PRE" %}
        {% assign next_game = g %}
        {% assign has_next = true %}
      {% endif %}
    {% endunless %}
  {% endfor %}
{% endfor %}

{% if has_prev %}
  {% if prev_game.homeTeam.abbrev == team %}
    {% assign p_us = prev_game.homeTeam %}
    {% assign p_them = prev_game.awayTeam %}
    {% assign p_where = "vs" %}
  {% else %}
    {% assign p_us = prev_game.awayTeam %}
    {% assign p_them = prev_game.homeTeam %}
    {% assign p_where = "at" %}
  {% endif %}
  {% assign p_type = prev_game.periodDescriptor.periodType | default: "REG" %}
  {% if p_us.score > p_them.score %}
    {% assign p_result = "W" %}
  {% elsif p_type == "REG" %}
    {% assign p_result = "L" %}
  {% else %}
    {% assign p_result = "OTL" %}
  {% endif %}
  {% assign p_date = prev_game.startTimeUTC | date: "%s" | plus: off | date: "%Y-%m-%d" %}
  {% if p_date == today %}
    {% assign p_day = "Today" %}
  {% elsif p_date == yesterday %}
    {% assign p_day = "Yesterday" %}
  {% else %}
    {% assign p_day = prev_game.startTimeUTC | date: "%s" | plus: off | date: "%a, %b %-d" %}
  {% endif %}
  {% capture p_final %}Final{% if p_type != "REG" %}/{{ p_type }}{% endif %}{% endcapture %}
{% endif %}

{% if has_next %}
  {% if next_game.homeTeam.abbrev == team %}
    {% assign n_us = next_game.homeTeam %}
    {% assign n_them = next_game.awayTeam %}
    {% assign n_where = "vs" %}
  {% else %}
    {% assign n_us = next_game.awayTeam %}
    {% assign n_them = next_game.homeTeam %}
    {% assign n_where = "at" %}
  {% endif %}
  {% assign n_live = false %}
  {% if next_game.gameState == "LIVE" or next_game.gameState == "CRIT" %}
    {% assign n_live = true %}
  {% endif %}
  {% assign n_ts = next_game.startTimeUTC | date: "%s" %}
  {% assign n_local_ts = n_ts | plus: off %}
  {% assign n_date = n_local_ts | date: "%Y-%m-%d" %}
  {% if n_date == today %}
    {% assign n_day = "Today" %}
  {% elsif n_date == tomorrow %}
    {% assign n_day = "Tomorrow" %}
  {% else %}
    {% assign n_day = n_local_ts | date: "%a, %b %-d" %}
  {% endif %}
  {% assign n_time = n_local_ts | date: "%-I:%M %p" %}
  {% assign n_period = next_game.periodDescriptor.number | default: 1 %}
  {% if next_game.periodDescriptor.periodType == "OT" %}
    {% assign n_period_label = "OT" %}
  {% elsif next_game.periodDescriptor.periodType == "SO" %}
    {% assign n_period_label = "Shootout" %}
  {% else %}
    {% assign n_period_label = n_period | ordinalize %}
  {% endif %}
{% endif %}

{% assign has_me = false %}
{% for t in IDX_1.standings %}
  {% if t.teamAbbrev.default == team %}
    {% assign me = t %}
    {% assign has_me = true %}
  {% endif %}
{% endfor %}

{% if has_me %}
  {% assign division = IDX_1.standings | where: "divisionAbbrev", me.divisionAbbrev | sort: "divisionSequence" %}
  {% assign record = me.wins | append: "–" | append: me.losses | append: "–" | append: me.otLosses %}
  {% assign nickname = me.teamCommonName.default %}
  {% assign max_pts = 1 %}
  {% for d_team in division %}
    {% if d_team.points > max_pts %}
      {% assign max_pts = d_team.points %}
    {% endif %}
  {% endfor %}
{% else %}
  {% assign nickname = team %}
{% endif %}

{% assign as_of = IDX_1.standings.first.date | append: "T12:00:00" | date: "%b %-d" %}
"}}

