{% assign tomorrow = "now" | date: "%s" | plus: off | plus: 86400 | date: "%Y-%m-%d" %}
{% assign yesterday = "now" | date: "%s" | plus: off | minus: 86400 | date: "%Y-%m-%d" %}

{% assign has_prev = false %}
{% assign has_next = false %}
