<div class="layout layout--col" style="font-family:var(--value-font-family);gap:0;padding:6px 16px 0;height:434px;justify-content:space-between;align-items:stretch">
  <!-- Header: Enormous Team Logo + Live Game Score/Time + Record -->
  <div class="flex flex--row flex--between stretch-x" style="align-items:center;padding-bottom:6px;border-bottom:3px solid #000">
    <div class="flex flex--row" style="align-items:center;gap:18px">
      {% if logo_url %}
        <img src="{{ logo_url }}" style="width:120px;height:120px;object-fit:contain;filter:grayscale(100%) contrast(200%);image-rendering:pixelated" alt="{{ team }}">
      {% endif %}
      {% if live_game %}
        <div style="border-left:3px solid #000;padding-left:14px">
          <span class="label label--small label--inverted" style="padding:2px 8px;font-weight:800">LIVE · {{ live_period_label }}{% if live_game.clock.timeRemaining %} · {{ live_game.clock.timeRemaining }}{% endif %}</span>
          <div class="flex flex--row" style="align-items:baseline;gap:8px;margin-top:4px">
            <span class="value value--tnums" style="font-size:40px;line-height:1;font-weight:800">{{ live_us.score | default: 0 }}–{{ live_them.score | default: 0 }}</span>
            <span style="font-size:18px;font-weight:700">{{ live_where }} {{ live_them.commonName.default }}</span>
          </div>
        </div>
      {% endif %}
    </div>
    {% if has_me %}
    <div class="text--right">
      <span class="value value--tnums" style="font-size:38px;line-height:1">{{ record }}</span>
      <div class="label label--small" style="display:block;margin-top:6px">{{ me.points }} pts · {{ me.divisionSequence | ordinalize }} in {{ me.divisionName }} · {{ me.streakCode }}{{ me.streakCount }}</div>
    </div>
    {% endif %}
  </div>

  <!-- Games Section: 1/3 Last Game, 2/3 Next Game -->
  <div class="flex flex--row stretch-x" style="align-items:stretch;border-bottom:3px solid #000;min-height:116px">
    <!-- Last Game (1/3) -->
    <div style="flex:1;min-width:0;padding:10px 14px 8px 0;border-right:3px solid #000">
      <span class="label label--small">Last game</span>
      {% if has_prev %}
      <div class="flex flex--row" style="align-items:center;justify-content:flex-start;gap:10px;margin-top:4px">
        <span style="background:#000;color:#fff;font-weight:800;font-size:22px;line-height:1;padding:3px 7px">{{ p_result }}</span>
        <span class="value value--tnums" style="font-size:40px;line-height:.9">{{ p_us.score }}–{{ p_them.score }}</span>
      </div>
      <div style="margin-top:6px;font-size:16px;line-height:1.2;white-space:nowrap;overflow:hidden;text-overflow:ellipsis">{{ p_where }} <b>{{ p_them.commonName.default }}</b> · {{ p_day }}{% if p_type != "REG" %} · {{ p_type }}{% endif %}</div>
      {% else %}
      <div class="description" style="margin-top:8px">No recent games.</div>
      {% endif %}
    </div>

    <!-- Next Game (2/3) -->
    <div style="flex:2;min-width:0;padding:10px 0 8px 16px;display:flex;flex-direction:column;justify-content:space-between">
      {% if has_next %}
        <div>
          <span class="label label--small">Next game</span>
          <div class="flex flex--row" style="align-items:center;gap:10px;margin-top:4px">
            <span style="font-size:24px;font-weight:700">{{ n_where }}</span>
            {% if n_them.logo %}
              <img src="{{ n_them.logo }}" style="width:44px;height:44px;object-fit:contain;filter:grayscale(100%) contrast(200%);image-rendering:pixelated" alt="{{ n_them.commonName.default }}">
            {% endif %}
            <span class="value" style="font-size:32px;line-height:1;font-weight:800;white-space:nowrap;overflow:hidden;text-overflow:ellipsis">{{ n_them.commonName.default }}</span>
          </div>
        </div>

        <!-- Bottom line aligned with baseline: game date/time + smaller subtle subtext for next home game -->
        <div class="flex flex--row flex--between stretch-x" style="align-items:baseline;margin-top:6px;gap:8px">
          <div class="value value--tnums" style="font-size:22px;line-height:1;font-weight:700">{{ n_day }} · {{ n_time }}</div>
          {% if has_sub %}
            <div class="flex flex--row" style="align-items:center;gap:5px;font-size:14px;font-weight:700;white-space:nowrap">
              <span style="text-transform:uppercase;font-size:11px;letter-spacing:0.5px;font-weight:800;background:#000;color:#fff;padding:1px 4px">{{ sub_header }}</span>
              <span>{{ sub_where }}</span>
              {% if sub_them.logo %}
