              {% endif %}
              <span class="value--tnums">{{ sub_day }} {{ sub_time }}</span>
            </div>
          {% endif %}
        </div>
      {% else %}
        <span class="label label--small">Next game</span>
        <div class="description" style="margin-top:8px">No upcoming games scheduled.</div>
      {% endif %}
    </div>
  </div>

  <!-- Division Standings: Vertical Bar Graph (1st to 8th) -->
  {% if has_me %}
  <div style="padding-top:10px">
    <div class="flex flex--row stretch-x" style="align-items:flex-end;justify-content:space-between;height:124px;padding:0 8px">
