          <span class="value value--tnums" style="font-size:17px;font-weight:800;line-height:1;margin-bottom:4px;{% if is_selected %}background:#000;color:#fff;padding:1px 4px{% endif %}">{{ t.points }}</span>
          {% if forloop.index <= 2 %}
            <div style="width:46px;height:{{ h }}px;background:#000"></div>
          {% elsif forloop.index == 3 %}
            <svg width="46" height="{{ h }}" style="display:block">
              <rect width="46" height="{{ h }}" fill="url(#crosshatch)" stroke="#000" stroke-width="2" />
            </svg>
          {% else %}
            <div style="box-sizing:border-box;width:46px;height:{{ h }}px;background:#fff;border:2px solid #000"></div>
          {% endif %}
          <div style="margin-top:5px;text-align:center;line-height:1">
            <div style="font-size:15px;font-weight:800;letter-spacing:-0.5px;{% if is_selected %}text-decoration:underline;text-decoration-thickness:2px{% endif %}">{{ t.teamAbbrev.default }}</div>
          </div>
        </div>
      {% endfor %}
    </div>
  </div>
  {% endif %}
