            <span style="font-size:18px;font-weight:700">{{ live_where }} {{ live_them.commonName.default }}</span>
          </div>
        </div>
      {% endif %}
    </div>
    {% if has_me %}
    <div class="text--right">
      <span class="value value--tnums" style="font-size:38px;line-height:1">{{ record }}</span>
      <div class="label label--small" style="display:block;margin-top:2px">{{ me.points }} pts · {{ me.divisionSequence | ordinalize }} in {{ me.divisionName }} · {{ me.streakCode }}{{ me.streakCount }}</div>
