        <span style="background:#000;color:#fff;font-weight:800;font-size:22px;line-height:1;padding:4px 8px">{{ p_result }}</span>
        <span class="value value--tnums" style="font-size:42px;line-height:.9;font-weight:800">{{ p_us.score }}–{{ p_them.score }}</span>
      </div>
      <div style="margin-top:8px;font-size:18px;line-height:1.2;font-weight:700;text-align:left">
        {{ p_loc_label }} <span style="font-weight:400">{{ p_them.commonName.default }}</span><br>
        <span class="value--tnums" style="font-size:15px;font-weight:600">{{ p_day }}{% if p_type != "REG" %} · {{ p_type }}{% endif %}</span>
      </div>
      {% else %}
      <div class="description" style="text-align:left">No recent games.</div>
      {% endif %}
    </div>

    <!-- Next Games Grid -->
    <div style="flex:1;min-width:0;padding-left:16px;display:flex;flex-direction:column;justify-content:space-between">
      <div class="flex flex--row flex--between" style="align-items:center;margin-bottom:2px">
        <span class="label label--small">Upcoming</span>
      </div>
      {% for row in upcoming_list limit:4 %}
        <div class="flex flex--row" style="align-items:center;height:38px;border-bottom:1px dotted #ccc;{% if row.is_next_home %}background:#efefef;padding:0 6px;margin:0 -6px;{% endif %}">
