  </div>

  <!-- Mid Section: Last Game 1/3 + Upcoming 2/3 (vertically centered, no labels) -->
  <div class="flex flex--row stretch-x" style="align-items:stretch;border-bottom:3px solid #000;padding:0;flex:1">
    <!-- Last Game -->
    <div style="width:220px;flex-shrink:0;padding-right:16px;border-right:3px solid #000;display:flex;flex-direction:column;justify-content:center;text-align:left">
      {% if has_prev %}
      <div class="flex flex--row" style="align-items:center;gap:10px;justify-content:flex-start">
        <span style="background:#000;color:#fff;font-weight:800;font-size:22px;line-height:1;padding:4px 8px">{{ p_result }}</span>
        <span class="value value--tnums" style="font-size:42px;line-height:.9;font-weight:800">{{ p_us.score }}–{{ p_them.score }}</span>
      </div>
      <div style="margin-top:8px;font-size:18px;line-height:1.2;text-align:left">
