          </div>
          <!-- Col 3: Opponent Name -->
          <div style="width:150px;font-size:16px;font-weight:500;white-space:nowrap;overflow:hidden;text-overflow:ellipsis">
            {{ row.them.commonName.default }}
          </div>
          <!-- Col 4: Day -->
          <div style="width:105px;font-size:15px;font-weight:600;white-space:nowrap" class="value--tnums">
            {{ row.day }}
          </div>
          <!-- Col 5: Time -->
          <div style="flex:1;text-align:right;font-size:15px;font-weight:700;white-space:nowrap" class="value--tnums">
            {{ row.time }}
          </div>
        </div>
