{% endtemplate %}","full":"{% assign zip_info = IDX_0 %}
{% assign weather = IDX_1 | default: this %}
{% assign place = zip_info.places[0] %}
{% assign location_label = place['place name'] | default: zipcode | default: 'Seattle' %}
{% if place['state abbreviation'] %}
  {% assign location_label = location_label | append: ', ' | append: place['state abbreviation'] %}
{% endif %}
{% assign date_label = weather.daily.time[0] | date: "%a, %b %-d" %}
{% assign current_temp = weather.current.temperature_2m | default: weather.daily.temperature_2m_max[0] | round %}

<div class="layout layout--col" style="padding:16px 24px 8px 24px;box-sizing:border-box;height:480px;justify-content:space-between;font-family:sans-serif;">
  <!-- TODAY SECTION -->
  <div style="display:flex;align-items:flex-end;justify-content:space-between;border-bottom:3px solid #000;padding-bottom:12px;">
    <!-- Today Info, Current Temp, High/Low stacked -->
    <div style="display:flex;flex-direction:column;width:300px;">
      <div style="font-size:18px;font-weight:700;line-height:1.2;color:#000;">{{ date_label }} in {{ location_label }}</div>
      <div style="display:flex;align-items:center;gap:16px;margin-top:8px;">
        <span class="value value--tnums" style="font-size:74px;line-height:0.9;font-weight:800;color:#000;">{{ current_temp }}&deg;</span>
        <div style="display:flex;flex-direction:column;justify-content:center;gap:3px;">
          <span class="value value--tnums" style="font-size:24px;line-height:1;font-weight:700;color:#000;">{{ weather.daily.temperature_2m_max[0] | round }}&deg;</span>
          <span class="value value--tnums" style="font-size:24px;line-height:1;font-weight:700;color:#000;">{{ weather.daily.temperature_2m_min[0] | round }}&deg;</span>
        </div>
      </div>
      <div style="display:flex;align-items:center;gap:10px;margin-top:10px;">
        <div style="width:28px;height:28px;display:flex;align-items:center;justify-content:center;">
          {% render "weather_icon", code: weather.daily.weather_code[0] %}
        </div>
        <span style="font-size:15px;font-weight:700;color:#000;">{{ weather.daily.precipitation_probability_mean[0] | round }}% RAIN</span>
      </div>
    </div>

    <!-- Today Precip Line Graph (5am-11pm) -->
    <div style="display:flex;flex-direction:column;width:440px;">
      <div style="display:flex;justify-content:space-between;margin-bottom:4px;">
        <span style="font-size:12px;font-weight:700;letter-spacing:0.5px;color:#000;">PRECIPITATION</span>
        <span style="font-size:12px;font-weight:700;color:#000;">100%</span>
      </div>
      <div style="border-left:2px solid #000;border-bottom:2px solid #000;height:90px;width:100%;position:relative;">
        <svg viewBox="0 0 440 90" style="width:100%;height:90px;display:block;overflow:hidden;">
          <defs>
            <pattern id="hatch-today" width="6" height="6" patternUnits="userSpaceOnUse" patternTransform="rotate(45)">
              <rect width="1.5" height="6" fill="#000" />
            </pattern>
          </defs>
          <line x1="0" y1="45" x2="440" y2="45" stroke="#000" stroke-width="1" stroke-dasharray="3 3" opacity="0.6" />
          {% capture pts %}
            {% for h in (5..23) %}
              {% assign val = weather.hourly.precipitation_probability[h] | default: 0 %}
              {% assign step = h | minus: 5 %}
              {% assign x = step | times: 440 | divided_by: 18 %}
              {% assign y = 100 | minus: val | times: 90 | divided_by: 100 %}
              {{ x }},{{ y }}
            {% endfor %}
          {% endcapture %}
          {% assign max_p = 0 %}
          {% for h in (5..23) %}
            {% assign p_val = weather.hourly.precipitation_probability[h] | default: 0 %}
            {% if p_val > max_p %}{% assign max_p = p_val %}{% endif %}
          {% endfor %}
          {% if max_p > 0 %}
            <polygon points="0,90 {{ pts | strip }} 440,90" fill="url(#hatch-today)" />
          {% endif %}
          <polyline fill="none" stroke="#000" stroke-width="3" stroke-linejoin="round" stroke-linecap="round" points="{{ pts | strip }}" />
        </svg>
      </div>
      <div style="display:flex;justify-content:space-between;margin-top:4px;">
        <span style="font-size:11px;font-weight:700;color:#000;">5 AM</span>
        <span style="font-size:11px;font-weight:700;color:#000;">9 AM</span>
        <span style="font-size:11px;font-weight:700;color:#000;">1 PM</span>
        <span style="font-size:11px;font-weight:700;color:#000;">5 PM</span>
        <span style="font-size:11px;font-weight:700;color:#000;">8 PM</span>
        <span style="font-size:11px;font-weight:700;color:#000;">11 PM</span>
      </div>
    </div>
  </div>

  <!-- NEXT 5 DAYS FORECAST -->
  <div style="display:flex;flex-direction:row;justify-content:space-between;gap:12px;margin-top:10px;margin-bottom:6px;">
    {% for d in (1..5) %}
      {% assign start_idx = d | times: 24 %}
      <div style="flex:1;display:flex;flex-direction:column;{% unless forloop.last %}border-right:1px solid #000;padding-right:10px;{% endunless %}">
        <div style="display:flex;justify-content:space-between;align-items:center;">
          <span style="font-size:16px;font-weight:800;color:#000;">{{ weather.daily.time[d] | date: "%a" | upcase }}</span>
          <div style="width:24px;height:24px;">
            {% render "weather_icon", code: weather.daily.weather_code[d] %}
          </div>
        </div>

        <div style="margin-top:4px;">
          <span class="value value--tnums" style="font-size:24px;font-weight:700;line-height:1;color:#000;">{{ weather.daily.temperature_2m_max[d] | round }}&deg;</span>
          <span class="value value--tnums" style="font-size:18px;font-weight:600;color:#000;">/{{ weather.daily.temperature_2m_min[d] | round }}&deg;</span>
        </div>

        <!-- 5am-11pm mini sparkline -->
        <div style="margin-top:8px;border-left:1px solid #000;border-bottom:1px solid #000;height:48px;position:relative;">
          <svg viewBox="0 0 120 48" style="width:100%;height:48px;display:block;overflow:hidden;">
            <defs>
              <pattern id="hatch-{{ d }}" width="5" height="5" patternUnits="userSpaceOnUse" patternTransform="rotate(45)">
                <rect width="1.5" height="5" fill="#000" />
              </pattern>
            </defs>
            <line x1="0" y1="24" x2="120" y2="24" stroke="#000" stroke-width="1" stroke-dasharray="2 2" opacity="0.5" />
            {% capture dpts %}
              {% for h in (5..23) %}
                {% assign cur = start_idx | plus: h %}
                {% assign val = weather.hourly.precipitation_probability[cur] | default: 0 %}
                {% assign step = h | minus: 5 %}
                {% assign x = step | times: 120 | divided_by: 18 %}
                {% assign y = 100 | minus: val | times: 48 | divided_by: 100 %}
                {{ x }},{{ y }}
              {% endfor %}
            {% endcapture %}

            {% assign d_max = 0 %}
            {% for h in (5..23) %}
              {% assign cur = start_idx | plus: h %}
              {% assign p_val = weather.hourly.precipitation_probability[cur] | default: 0 %}
              {% if p_val > d_max %}{% assign d_max = p_val %}{% endif %}
            {% endfor %}
            {% if d_max > 0 %}
              <polygon points="0,48 {{ dpts | strip }} 120,48" fill="url(#hatch-{{ d }})" />
            {% endif %}
            <polyline fill="none" stroke="#000" stroke-width="2.5" stroke-linejoin="round" points="{{ dpts | strip }}" />
          </svg>
        </div>

        <div style="display:flex;justify-content:space-between;align-items:baseline;margin-top:6px;">
          <span style="font-size:12px;font-weight:700;letter-spacing:0.5px;color:#000;">AVG</span>
          <span class="value value--tnums" style="font-size:18px;font-weight:700;color:#000;">{{ weather.daily.precipitation_probability_mean[d] | round }}%</span>
        </div>
      </div>
    {% endfor %}
  </div>

  <!-- TITLE BAR -->
  <div class="title_bar" style="margin-top:auto;">
    <span class="title">{{ location_label }}</span>
    <span class="instance">Rain or No Rain &middot; Open-Meteo</span>
  </div>
</div>
