  {% assign high_num = range_parts.last | strip | remove: "$" | remove: "," | plus: 0 %}
  {% assign open_num = prev_close %}
{% endif %}

<!-- 1-Month historical points from IDX_2 -->
{% assign hist_rows = IDX_2.data.tradesTable.rows | reverse %}
{% assign start_date = hist_rows.first.date %}
{% assign end_date = hist_rows.last.date | default: "Today" %}

{% assign m_pts_str = "" %}
{% for r in hist_rows %}
  {% assign cp = r.close | remove: "$" | remove: "," | plus: 0 %}
  {% if cp > 0 %}
    {% assign m_pts_str = m_pts_str | append: cp | append: "," %}
  {% endif %}
{% endfor %}
{% if cur_price > 0 %}
  {% assign m_pts_str = m_pts_str | append: cur_price | append: "," %}
{% endif %}
{% assign m_list = m_pts_str | split: "," %}
{% assign m_lo = 9999999 %}
{% assign m_hi = 0 %}
{% for v_str in m_list %}
  {% assign v = v_str | plus: 0 %}
  {% if v > 0 %}
    {% if v < m_lo %}{% assign m_lo = v %}{% endif %}
    {% if v > m_hi %}{% assign m_hi = v %}{% endif %}
  {% endif %}
{% endfor %}
{% if m_lo == 9999999 %}{% assign m_lo = cur_price %}{% assign m_hi = cur_price | plus: 1 %}{% endif %}
{% if m_hi <= m_lo %}{% assign m_hi = m_lo | plus: 1 %}{% endif %}
{% assign m_span = m_hi | minus: m_lo %}
{% assign m_denom = m_list.size | minus: 1 %}
{% if m_denom < 1 %}{% assign m_denom = 1 %}{% endif %}

{% capture poly_month_full %}
{% for v_str in m_list %}
  {% assign v = v_str | plus: 0 %}
  {% assign x = forloop.index0 | times: 784 | divided_by: m_denom %}
  {% assign y = m_hi | minus: v | times: 216 | divided_by: m_span | round: 1 %}
  {{ x }},{{ y }} 
{% endfor %}
{% endcapture %}

{% capture poly_month_half %}
{% for v_str in m_list %}
  {% assign v = v_str | plus: 0 %}
  {% assign x = forloop.index0 | times: 384 | divided_by: m_denom %}
  {% assign y = m_hi | minus: v | times: 180 | divided_by: m_span | round: 1 %}
  {{ x }},{{ y }} 
{% endfor %}
{% endcapture %}

<!-- Today Intraday Points from IDX_1 -->
{% assign chart_data = IDX_1.data.chart %}
{% assign parsed_pts = "" %}
{% assign p_count = 0 %}
{% for p in chart_data %}
  {% assign v = p.z.value | default: p.y | default: p.value | default: p.z | remove: "$" | remove: "," | plus: 0 %}
  {% if v > 0 %}
    {% assign parsed_pts = parsed_pts | append: v | append: "," %}
    {% assign p_count = p_count | plus: 1 %}
  {% endif %}
{% endfor %}

{% if p_count == 0 %}
  {% assign p_1 = open_num %}
  {% if change >= 0 %}
    {% assign p_2 = low_num %}
    {% assign p_3 = high_num %}
  {% else %}
    {% assign p_2 = high_num %}
    {% assign p_3 = low_num %}
  {% endif %}
  {% assign p_4 = cur_price %}
  {% assign parsed_pts = p_1 | append: "," | append: p_2 | append: "," | append: p_3 | append: "," | append: p_4 | append: "," %}
{% endif %}

{% assign t_list = parsed_pts | split: "," %}
{% assign t_denom = t_list.size | minus: 1 %}
{% if t_denom < 1 %}{% assign t_denom = 1 %}{% endif %}

{% assign day_hi = high_num %}
{% assign day_lo = low_num %}
{% for val_str in t_list %}
  {% assign val = val_str | plus: 0 %}
  {% if val > 0 %}
    {% if day_lo == 0 or val < day_lo %}{% assign day_lo = val %}{% endif %}
    {% if val > day_hi %}{% assign day_hi = val %}{% endif %}
  {% endif %}
{% endfor %}
{% if prev_close > 0 %}
  {% if prev_close < day_lo %}{% assign day_lo = prev_close %}{% endif %}
  {% if prev_close > day_hi %}{% assign day_hi = prev_close %}{% endif %}
{% endif %}
{% if day_hi <= day_lo %}{% assign day_hi = day_lo | plus: 1 %}{% endif %}
{% assign t_span = day_hi | minus: day_lo %}

{% capture poly_today_full_spark %}
{% for val_str in t_list %}
  {% assign val = val_str | plus: 0 %}
  {% assign x = forloop.index0 | times: 300 | divided_by: t_denom %}
  {% assign y = day_hi | minus: val | times: 38 | divided_by: t_span | plus: 3 | round: 1 %}
  {{ x }},{{ y }} 
{% endfor %}
{% endcapture %}

{% capture poly_today_half_spark %}
{% for val_str in t_list %}
  {% assign val = val_str | plus: 0 %}
  {% assign x = forloop.index0 | times: 110 | divided_by: t_denom %}
  {% assign y = day_hi | minus: val | times: 24 | divided_by: t_span | plus: 3 | round: 1 %}
  {{ x }},{{ y }} 
{% endfor %}
{% endcapture %}

{% template chart_line %}
<svg width="{{ w }}" height="{{ h }}" viewBox="0 0 {{ w }} {{ h }}" style="display:block;width:{{ w }}px;height:{{ h }}px;overflow:hidden">
  <defs>
    <pattern id="{{ hatch_id }}" width="6" height="6" patternUnits="userSpaceOnUse" patternTransform="rotate(45)">
      <line x1="0" y1="0" x2="0" y2="6" stroke="#000" stroke-width="1.5" />
    </pattern>
  </defs>
  <polygon points="0,{{ h }} {{ pts | strip }} {{ w }},{{ h }}" fill="url(#{{ hatch_id }})" />
  <polyline points="{{ pts | strip }}" fill="none" stroke="#000" stroke-width="3" stroke-linejoin="round" stroke-linecap="round" />
</svg>
{% endtemplate %}

{% template chart_today_inline %}
<svg viewBox="0 0 {{ w }} {{ h }}" preserveAspectRatio="none" style="display:block;width:100%;height:100%;overflow:visible">
  <polyline points="{{ pts | strip }}" fill="none" stroke="#000" stroke-width="2.5" stroke-linejoin="round" stroke-linecap="round" />
</svg>
{% endtemplate %}

{% template change_badge %}
{% if change < 0 %}
<span class="label label--inverted" style="font-size:{{ size }}px;padding:2px 8px">▼ {{ pct_str }}</span>
{% else %}
<span class="label label--underline" style="font-size:{{ size }}px">▲ {{ pct_str }}</span>
{% endif %}
{% endtemplate %}
