{% template moon_phase_graphic %}
{% assign r = size | divided_by: 2 %}
{% assign inner_r = r | minus: 4 %}
{% assign ph = curphase | downcase %}
<svg width="{{ size }}" height="{{ size }}" viewBox="0 0 {{ size }} {{ size }}" style="display:block;margin:0 auto">
  <defs>
    <!-- 45-degree hatch pattern for the lunar dark side/shadow -->
    <pattern id="lunar-shadow-{{ size }}" width="6" height="6" patternUnits="userSpaceOnUse" patternTransform="rotate(45)">
      <rect width="2.5" height="6" fill="#000"/>
    </pattern>
    <pattern id="crater-pattern-{{ size }}" width="8" height="8" patternUnits="userSpaceOnUse">
      <circle cx="3" cy="3" r="1.5" fill="#000"/>
      <circle cx="7" cy="7" r="1" fill="#000"/>
    </pattern>
  </defs>

  <!-- Outer ring & base disc -->
  <circle cx="{{ r }}" cy="{{ r }}" r="{{ inner_r }}" fill="#000" stroke="#000" stroke-width="3" />

  {% if ph contains "new" %}
    <!-- New Moon: shadowed disc with hatch fill and distinct rim -->
    <circle cx="{{ r }}" cy="{{ r }}" r="{{ inner_r | minus: 2 }}" fill="#fff" />
    <circle cx="{{ r }}" cy="{{ r }}" r="{{ inner_r | minus: 2 }}" fill="url(#lunar-shadow-{{ size }})" />
    <circle cx="{{ r }}" cy="{{ r }}" r="{{ inner_r }}" fill="none" stroke="#000" stroke-width="4" stroke-dasharray="6 4" />

  {% elsif ph contains "full" %}
    <!-- Full Moon: Solid bright disc with realistic crater/maria shapes -->
    <circle cx="{{ r }}" cy="{{ r }}" r="{{ inner_r | minus: 1 }}" fill="#fff" />
    <!-- Maria (dark plains) with crosshatch -->
    <circle cx="{{ r | minus: 15 }}" cy="{{ r | minus: 20 }}" r="12" fill="url(#crater-pattern-{{ size }})" />
    <circle cx="{{ r | plus: 20 }}" cy="{{ r | minus: 15 }}" r="15" fill="url(#crater-pattern-{{ size }})" />
    <circle cx="{{ r | minus: 10 }}" cy="{{ r | plus: 22 }}" r="18" fill="url(#crater-pattern-{{ size }})" />
    <circle cx="{{ r }}" cy="{{ r }}" r="{{ inner_r }}" fill="none" stroke="#000" stroke-width="4" />

  {% elsif ph contains "first quarter" %}
    <!-- First Quarter: Western half dark (hatched), Eastern half lit (white) -->
    <circle cx="{{ r }}" cy="{{ r }}" r="{{ inner_r | minus: 1 }}" fill="#fff" />
    <!-- Left half dark -->
    <path d="M {{ r }} {{ r | minus: inner_r }} A {{ inner_r }} {{ inner_r }} 0 0 0 {{ r }} {{ r | plus: inner_r }} Z" fill="url(#lunar-shadow-{{ size }})" />
    <circle cx="{{ r }}" cy="{{ r }}" r="{{ inner_r }}" fill="none" stroke="#000" stroke-width="4" />
    <line x1="{{ r }}" y1="{{ r | minus: inner_r }}" x2="{{ r }}" y2="{{ r | plus: inner_r }}" stroke="#000" stroke-width="2" />

  {% elsif ph contains "last quarter" %}
    <!-- Last Quarter: Eastern half dark, Western half lit -->
    <circle cx="{{ r }}" cy="{{ r }}" r="{{ inner_r | minus: 1 }}" fill="#fff" />
    <!-- Right half dark -->
    <path d="M {{ r }} {{ r | minus: inner_r }} A {{ inner_r }} {{ inner_r }} 0 0 1 {{ r }} {{ r | plus: inner_r }} Z" fill="url(#lunar-shadow-{{ size }})" />
    <circle cx="{{ r }}" cy="{{ r }}" r="{{ inner_r }}" fill="none" stroke="#000" stroke-width="4" />
    <line x1="{{ r }}" y1="{{ r | minus: inner_r }}" x2="{{ r }}" y2="{{ r | plus: inner_r }}" stroke="#000" stroke-width="2" />

  {% elsif ph contains "waxing crescent" %}
    <!-- Waxing Crescent: Right crescent lit (white), rest dark -->
    <circle cx="{{ r }}" cy="{{ r }}" r="{{ inner_r | minus: 1 }}" fill="url(#lunar-shadow-{{ size }})" />
    <!-- Bright crescent on right side -->
    <path d="M {{ r }} {{ r | minus: inner_r }} A {{ inner_r }} {{ inner_r }} 0 0 1 {{ r }} {{ r | plus: inner_r }} A {{ inner_r | times: 0.55 }} {{ inner_r }} 0 0 0 {{ r }} {{ r | minus: inner_r }} Z" fill="#fff" stroke="#000" stroke-width="1.5" />
    <circle cx="{{ r }}" cy="{{ r }}" r="{{ inner_r }}" fill="none" stroke="#000" stroke-width="4" />

  {% elsif ph contains "waning crescent" %}
    <!-- Waning Crescent: Left crescent lit (white), rest dark -->
    <circle cx="{{ r }}" cy="{{ r }}" r="{{ inner_r | minus: 1 }}" fill="url(#lunar-shadow-{{ size }})" />
    <!-- Bright crescent on left side -->
    <path d="M {{ r }} {{ r | minus: inner_r }} A {{ inner_r }} {{ inner_r }} 0 0 0 {{ r }} {{ r | plus: inner_r }} A {{ inner_r | times: 0.55 }} {{ inner_r }} 0 0 1 {{ r }} {{ r | minus: inner_r }} Z" fill="#fff" stroke="#000" stroke-width="1.5" />
    <circle cx="{{ r }}" cy="{{ r }}" r="{{ inner_r }}" fill="none" stroke="#000" stroke-width="4" />

  {% elsif ph contains "waxing gibbous" %}
    <!-- Waxing Gibbous: Most of right and middle lit, crescent shadow on left -->
    <circle cx="{{ r }}" cy="{{ r }}" r="{{ inner_r | minus: 1 }}" fill="#fff" />
    <circle cx="{{ r | minus: 5 }}" cy="{{ r | minus: 15 }}" r="12" fill="url(#crater-pattern-{{ size }})" />
    <circle cx="{{ r | plus: 18 }}" cy="{{ r | plus: 10 }}" r="14" fill="url(#crater-pattern-{{ size }})" />
    <!-- Left shadow sliver -->
    <path d="M {{ r }} {{ r | minus: inner_r }} A {{ inner_r }} {{ inner_r }} 0 0 0 {{ r }} {{ r | plus: inner_r }} A {{ inner_r | times: 0.45 }} {{ inner_r }} 0 0 1 {{ r }} {{ r | minus: inner_r }} Z" fill="url(#lunar-shadow-{{ size }})" stroke="#000" stroke-width="1.5" />
    <circle cx="{{ r }}" cy="{{ r }}" r="{{ inner_r }}" fill="none" stroke="#000" stroke-width="4" />

  {% elsif ph contains "waning gibbous" %}
    <!-- Waning Gibbous: Most of left and middle lit, crescent shadow on right -->
    <circle cx="{{ r }}" cy="{{ r }}" r="{{ inner_r | minus: 1 }}" fill="#fff" />
    <circle cx="{{ r | plus: 5 }}" cy="{{ r | minus: 15 }}" r="12" fill="url(#crater-pattern-{{ size }})" />
    <circle cx="{{ r | minus: 18 }}" cy="{{ r | plus: 10 }}" r="14" fill="url(#crater-pattern-{{ size }})" />
    <!-- Right shadow sliver -->
    <path d="M {{ r }} {{ r | minus: inner_r }} A {{ inner_r }} {{ inner_r }} 0 0 1 {{ r }} {{ r | plus: inner_r }} A {{ inner_r | times: 0.45 }} {{ inner_r }} 0 0 0 {{ r }} {{ r | minus: inner_r }} Z" fill="url(#lunar-shadow-{{ size }})" stroke="#000" stroke-width="1.5" />
    <circle cx="{{ r }}" cy="{{ r }}" r="{{ inner_r }}" fill="none" stroke="#000" stroke-width="4" />

