{% for item in d.moondata %}
  {% if item.phen == "Rise" %}
    {% assign parts = item.time | split: ":" %}
    {% assign h = parts[0] | plus: 0 %}
    {% assign m = parts[1] %}
    {% if h >= 12 %}
      {% assign m_rise_ampm = "PM" %}
      {% if h > 12 %}{% assign h = h | minus: 12 %}{% endif %}
    {% else %}
      {% assign m_rise_ampm = "AM" %}
      {% if h == 0 %}{% assign h = 12 %}{% endif %}
    {% endif %}
    {% capture m_rise %}{{ h }}:{{ m }}{% endcapture %}
  {% endif %}
  {% if item.phen == "Set" %}
    {% assign parts = item.time | split: ":" %}
    {% assign h = parts[0] | plus: 0 %}
    {% assign m = parts[1] %}
    {% if h >= 12 %}
      {% assign m_set_ampm = "PM" %}
      {% if h > 12 %}{% assign h = h | minus: 12 %}{% endif %}
    {% else %}
      {% assign m_set_ampm = "AM" %}
      {% if h == 0 %}{% assign h = 12 %}{% endif %}
    {% endif %}
    {% capture m_set %}{{ h }}:{{ m }}{% endcapture %}
  {% endif %}
  {% if item.phen == "Upper Transit" %}
    {% assign parts = item.time | split: ":" %}
    {% assign h = parts[0] | plus: 0 %}
    {% assign m = parts[1] %}
    {% if h >= 12 %}
      {% if h > 12 %}{% assign h = h | minus: 12 %}{% endif %}
      {% capture m_transit %}{{ h }}:{{ m }} PM{% endcapture %}
    {% else %}
      {% if h == 0 %}{% assign h = 12 %}{% endif %}
      {% capture m_transit %}{{ h }}:{{ m }} AM{% endcapture %}
    {% endif %}
  {% endif %}
{% endfor %}

{% assign s_dawn = "—" %}
