strategy: polling
framework_version: 3.2.0
polling_verb: get
polling_url: |-
  {% assign chosen_city = city | default: 'Seattle' %}
  {% case chosen_city %}
  {% when 'San Francisco' %}
    {% assign c_lat = '37.7749' %}{% assign c_lon = '-122.4194' %}
  {% when 'Portland' %}
    {% assign c_lat = '45.5152' %}{% assign c_lon = '-122.6784' %}
  {% when 'New York' %}
    {% assign c_lat = '40.7128' %}{% assign c_lon = '-74.0060' %}
  {% when 'Chicago' %}
    {% assign c_lat = '41.8781' %}{% assign c_lon = '-87.6298' %}
  {% when 'Denver' %}
    {% assign c_lat = '39.7392' %}{% assign c_lon = '-104.9903' %}
  {% when 'Austin' %}
    {% assign c_lat = '30.2672' %}{% assign c_lon = '-97.7431' %}
  {% when 'Los Angeles' %}
    {% assign c_lat = '34.0522' %}{% assign c_lon = '-118.2437' %}
  {% when 'London' %}
    {% assign c_lat = '51.5074' %}{% assign c_lon = '-0.1278' %}
  {% when 'Berlin' %}
    {% assign c_lat = '52.5200' %}{% assign c_lon = '13.4050' %}
  {% when 'Tokyo' %}
    {% assign c_lat = '35.6762' %}{% assign c_lon = '139.6503' %}
  {% else %}
    {% assign c_lat = '47.6062' %}{% assign c_lon = '-122.3321' %}
  {% endcase %}
  https://api.open-meteo.com/v1/forecast?latitude={{ c_lat }}&longitude={{ c_lon }}&daily=weather_code,temperature_2m_max,temperature_2m_min,precipitation_probability_mean&hourly=precipitation_probability&forecast_days=6&timezone=auto&temperature_unit={{ units | default: 'fahrenheit' }}
polling_headers: accept=application/json&user-agent=Mozilla/5.0 (compatible; GarageScreen/1.0)
custom_fields:
- keyname: about
  field_type: author_bio
  name: About This Plugin
  description: Shows today's high/low with 24h hourly precipitation line graph, plus 5-day forecast with daily hourly precipitation sparklines and weather icons.
  category: weather
- keyname: city
  field_type: select
  name: City
  options:
  - Seattle: Seattle
  - San Francisco: San Francisco
  - Portland: Portland
  - New York: New York
  - Chicago: Chicago
  - Denver: Denver
  - Austin: Austin
  - Los Angeles: Los Angeles
  - London: London
  - Berlin: Berlin
  - Tokyo: Tokyo
  default: Seattle
  help_text: Select a city for forecast and hourly precipitation
- keyname: units
  field_type: select
  name: Temperature Units
  options:
  - Fahrenheit: fahrenheit
  - Celsius: celsius
  default: fahrenheit","shared.liquid":"{% template weather_icon %}
