    <line x1="12" y1="1" x2="12" y2="4" stroke="#000" stroke-width="2" stroke-linecap="round" />
    <line x1="12" y1="20" x2="12" y2="23" stroke="#000" stroke-width="2" stroke-linecap="round" />
    <line x1="1" y1="12" x2="4" y2="12" stroke="#000" stroke-width="2" stroke-linecap="round" />
    <line x1="20" y1="12" x2="23" y2="12" stroke="#000" stroke-width="2" stroke-linecap="round" />
    <line x1="4.2" y1="4.2" x2="6.4" y2="6.4" stroke="#000" stroke-width="2" stroke-linecap="round" />
    <line x1="17.6" y1="17.6" x2="19.8" y2="19.8" stroke="#000" stroke-width="2" stroke-linecap="round" />
    <line x1="4.2" y1="19.8" x2="6.4" y2="17.6" stroke="#000" stroke-width="2" stroke-linecap="round" />
    <line x1="17.6" y1="6.4" x2="19.8" y2="4.2" stroke="#000" stroke-width="2" stroke-linecap="round" />
