  <svg viewBox="0 0 24 24" width="100%" height="100%">
    <path d="M5 12 A 3.5 3.5 0 0 1 5 5 A 4.5 4.5 0 0 1 17 5 A 3.5 3.5 0 0 1 17 12 Z" fill="#000" />
    <polygon points="12,13 8,19 12,19 10,23 16,17 12,17" fill="#000" />
  </svg>
{% else %}
  {% comment %} Default Cloud {% endcomment %}
  <svg viewBox="0 0 24 24" width="100%" height="100%">
    <path d="M6 18 A 4 4 0 0 1 6 10 A 5 5 0 0 1 18 10 A 4 4 0 0 1 18 18 Z" fill="#000" />
  </svg>
{% endif %}
{% endtemplate %}","full.liquid":"{% assign city_name = trmnl.plugin_settings.custom_fields_values.city | default: city | default: 'Seattle' %}
<div class="layout layout--col" style="padding:16px 22px 8px 22px;box-sizing:border-box;height:480px;justify-content:space-between;">
  <!-- TODAY SECTION -->
  <div style="display:flex;align-items:flex-end;justify-content:space-between;border-bottom:3px solid #000;padding-bottom:14px;">
    <!-- Today Temp & Icon -->
    <div style="display:flex;flex-direction:column;width:260px;">
      <div style="display:flex;align-items:center;gap:6px;margin-bottom:2px;">
        <span class="label" style="font-size:15px;letter-spacing:1px;font-weight:700;">CITY: {{ city_name | upcase }}</span>
        <span class="label" style="font-size:13px;border:1px solid #000;padding:1px 5px;font-weight:700;">&#9662; SELECT</span>
      </div>
      <div class="label" style="font-size:13px;letter-spacing:0.5px;">TODAY &middot; {{ daily.time[0] | date: "%a %b %-d" | upcase }}</div>
      <div style="display:flex;align-items:baseline;gap:8px;margin-top:2px;">
        <span class="value value--tnums" style="font-size:76px;line-height:0.9;font-weight:800;">{{ daily.temperature_2m_max[0] | round }}&deg;</span>
        <span class="value value--tnums" style="font-size:36px;font-weight:600;">/ {{ daily.temperature_2m_min[0] | round }}&deg;</span>
      </div>
      <div style="display:flex;align-items:center;gap:12px;margin-top:8px;">
        <div style="width:34px;height:34px;display:flex;align-items:center;justify-content:center;">
          {% render "weather_icon", code: daily.weather_code[0] %}
        </div>
        <span class="label" style="font-size:17px;font-weight:700;letter-spacing:0.5px;">{{ daily.precipitation_probability_mean[0] | round }}% RAIN</span>
      </div>
    </div>

    <!-- Today 24h Hourly Precip Line Graph -->
    <div style="display:flex;flex-direction:column;width:470px;">
      <div style="display:flex;justify-content:space-between;margin-bottom:4px;">
        <span class="label label--small" style="font-weight:700;">HOURLY PRECIPITATION (24H)</span>
        <span class="label label--small">100%</span>
      </div>
      <div style="border-left:2px solid #000;border-bottom:2px solid #000;height:90px;width:100%;position:relative;">
        <svg viewBox="0 0 470 90" style="width:100%;height:90px;display:block;overflow:hidden;">
          <defs>
            <pattern id="hatch-today" width="6" height="6" patternUnits="userSpaceOnUse" patternTransform="rotate(45)">
              <rect width="1.5" height="6" fill="#000" />
            </pattern>
          </defs>
          <line x1="0" y1="45" x2="470" y2="45" stroke="#000" stroke-width="1" stroke-dasharray="3 3" opacity="0.6" />
          {% capture pts %}
            {% for i in (0..23) %}
              {% assign val = hourly.precipitation_probability[i] | default: 0 %}
              {% assign x = i | times: 470 | divided_by: 23 %}
              {% assign y = 100 | minus: val | times: 90 | divided_by: 100 %}
              {{ x }},{{ y }}
            {% endfor %}
          {% endcapture %}
          {% assign max_p = 0 %}
          {% for i in (0..23) %}
            {% assign p_val = hourly.precipitation_probability[i] | default: 0 %}
            {% if p_val > max_p %}{% assign max_p = p_val %}{% endif %}
          {% endfor %}
          {% if max_p > 0 %}
            <polygon points="0,90 {{ pts | strip }} 470,90" fill="url(#hatch-today)" />
          {% endif %}
          <polyline fill="none" stroke="#000" stroke-width="3" stroke-linejoin="round" stroke-linecap="round" points="{{ pts | strip }}" />
        </svg>
      </div>
      <div style="display:flex;justify-content:space-between;margin-top:4px;">
        <span class="label label--small" style="font-size:11px;">12 AM</span>
        <span class="label label--small" style="font-size:11px;">6 AM</span>
        <span class="label label--small" style="font-size:11px;">12 PM</span>
        <span class="label label--small" style="font-size:11px;">6 PM</span>
        <span class="label label--small" style="font-size:11px;">11 PM</span>
      </div>
    </div>
  </div>

  <!-- NEXT 5 DAYS FORECAST -->
  <div style="display:flex;flex-direction:row;justify-content:space-between;gap:12px;margin-top:12px;margin-bottom:8px;">
    {% for d in (1..5) %}
      {% assign start_idx = d | times: 24 %}
      <div style="flex:1;display:flex;flex-direction:column;{% unless forloop.last %}border-right:1px solid #000;padding-right:10px;{% endunless %}">
        <div style="display:flex;justify-content:space-between;align-items:center;">
          <span class="label" style="font-size:16px;font-weight:700;">{{ daily.time[d] | date: "%a" | upcase }}</span>
          <div style="width:26px;height:26px;">
            {% render "weather_icon", code: daily.weather_code[d] %}
          </div>
        </div>

        <div style="margin-top:4px;">
          <span class="value value--tnums" style="font-size:26px;font-weight:700;line-height:1;">{{ daily.temperature_2m_max[d] | round }}&deg;</span>
          <span class="value value--tnums" style="font-size:18px;font-weight:500;">/{{ daily.temperature_2m_min[d] | round }}&deg;</span>
        </div>

        <!-- 24h mini sparkline -->
        <div style="margin-top:8px;border-left:1px solid #000;border-bottom:1px solid #000;height:48px;position:relative;">
          <svg viewBox="0 0 120 48" style="width:100%;height:48px;display:block;overflow:hidden;">
            <defs>
              <pattern id="hatch-{{ d }}" width="5" height="5" patternUnits="userSpaceOnUse" patternTransform="rotate(45)">
                <rect width="1.5" height="5" fill="#000" />
              </pattern>
            </defs>
            <line x1="0" y1="24" x2="120" y2="24" stroke="#000" stroke-width="1" stroke-dasharray="2 2" opacity="0.5" />
            {% capture dpts %}
              {% for h in (0..23) %}
                {% assign cur = start_idx | plus: h %}
                {% assign val = hourly.precipitation_probability[cur] | default: 0 %}
                {% assign x = h | times: 120 | divided_by: 23 %}
                {% assign y = 100 | minus: val | times: 48 | divided_by: 100 %}
                {{ x }},{{ y }}
              {% endfor %}
            {% endcapture %}

            {% assign d_max = 0 %}
            {% for h in (0..23) %}
              {% assign cur = start_idx | plus: h %}
              {% assign p_val = hourly.precipitation_probability[cur] | default: 0 %}
              {% if p_val > d_max %}{% assign d_max = p_val %}{% endif %}
            {% endfor %}
            {% if d_max > 0 %}
              <polygon points="0,48 {{ dpts | strip }} 120,48" fill="url(#hatch-{{ d }})" />
            {% endif %}
            <polyline fill="none" stroke="#000" stroke-width="2.5" stroke-linejoin="round" points="{{ dpts | strip }}" />
          </svg>
        </div>

        <div style="display:flex;justify-content:space-between;align-items:baseline;margin-top:6px;">
          <span class="label label--small" style="font-size:12px;">AVG</span>
          <span class="value value--tnums" style="font-size:18px;font-weight:700;">{{ daily.precipitation_probability_mean[d] | round }}%</span>
        </div>
      </div>
    {% endfor %}
  </div>

  <!-- TITLE BAR -->
  <div class="title_bar" style="margin-top:auto;">
    <span class="title">City: {{ city_name }} (Select in Settings)</span>
    <span class="instance">Open-Meteo &middot; Forecast &amp; Rain</span>
  </div>
</div>"}}

