","settings.yml":"name: Weather & Precip
strategy: polling
framework_version: 3.2.0
polling_verb: get
polling_url: |-
  {% assign zip_clean = zipcode | default: '98101' | strip %}
  https://api.zippopotam.us/us/{{ zip_clean }}
  https://api.open-meteo.com/v1/forecast?latitude={% if IDX_0.places[0].latitude %}{{ IDX_0.places[0].latitude }}{% else %}47.6062{% endif %}&longitude={% if IDX_0.places[0].longitude %}{{ IDX_0.places[0].longitude }}{% else %}-122.3321{% endif %}&daily=weather_code,temperature_2m_max,temperature_2m_min,precipitation_probability_mean&hourly=precipitation_probability&forecast_days=6&timezone=auto&temperature_unit={{ units | default: 'fahrenheit' }}
polling_headers: accept=application/json&user-agent=Mozilla/5.0 (compatible; GarageScreen/1.0)
custom_fields:
- keyname: about
  field_type: author_bio
  name: About This Plugin
  description: Shows today's high/low and precipitation graph (5 AM to 11 PM) plus 5-day forecast with precipitation sparklines for any US ZIP code.
  category: weather
- keyname: zipcode
  field_type: string
  name: ZIP Code
  default: '98101'
  placeholder: '98101'
  help_text: Enter any 5-digit US ZIP code
- keyname: units
  field_type: select
  name: Temperature Units
  options:
  - Fahrenheit: fahrenheit
  - Celsius: celsius
  default: fahrenheit
","shared.liquid":"{% template weather_icon %}
{% assign c = code | plus: 0 %}
