        <span class="label label--small" style="font-size:11px;">8 PM</span>
        <span class="label label--small" style="font-size:11px;">11 PM</span>
      </div>
    </div>
  </div>

  <!-- NEXT 5 DAYS FORECAST -->
  <div style="display:flex;flex-direction:row;justify-content:space-between;gap:12px;margin-top:10px;margin-bottom:6px;">
