strategy: polling
framework_version: 3.2.0
polling_verb: get
polling_url: |-
  {% assign zip_clean = zipcode | default: '98101' | strip %}
  https://api.zippopotam.us/us/{{ zip_clean }}
  https://api.open-meteo.com/v1/forecast?latitude={% if IDX_0.places[0].latitude %}{{ IDX_0.places[0].latitude }}{% else %}47.6062{% endif %}&longitude={% if IDX_0.places[0].longitude %}{{ IDX_0.places[0].longitude }}{% else %}-122.3321{% endif %}&current=temperature_2m&daily=weather_code,temperature_2m_max,temperature_2m_min,precipitation_probability_mean&hourly=precipitation_probability&forecast_days=6&timezone=auto&temperature_unit={{ units | default: 'fahrenheit' }}
polling_headers: accept=application/json&user-agent=Mozilla/5.0 (compatible; GarageScreen/1.0)
custom_fields:
- keyname: about
  field_type: author_bio
  name: About This Plugin
  description: Shows today's current temperature, high/low, and precipitation graph plus 5-day forecast with precipitation sparklines for any US ZIP code.
  category: weather
- keyname: zipcode
  field_type: string
  name: ZIP Code
  default: '98101'
  placeholder: '98101'
  help_text: Enter any 5-digit US ZIP code
- keyname: units
  field_type: select
  name: Temperature Units
  options:
  - Fahrenheit: fahrenheit
  - Celsius: celsius
  default: fahrenheit","shared.liquid":"{% template weather_icon %}
{% assign c = code | plus: 0 %}
{% if c == 0 %}
  {% comment %} Clear / Sunny {% endcomment %}
  <svg viewBox="0 0 24 24" width="100%" height="100%">
    <circle cx="12" cy="12" r="5" fill="#000" />
    <line x1="12" y1="1" x2="12" y2="4" stroke="#000" stroke-width="2" stroke-linecap="round" />
    <line x1="12" y1="20" x2="12" y2="23" stroke="#000" stroke-width="2" stroke-linecap="round" />
    <line x1="1" y1="12" x2="4" y2="12" stroke="#000" stroke-width="2" stroke-linecap="round" />
    <line x1="20" y1="12" x2="23" y2="12" stroke="#000" stroke-width="2" stroke-linecap="round" />
    <line x1="4.2" y1="4.2" x2="6.4" y2="6.4" stroke="#000" stroke-width="2" stroke-linecap="round" />
    <line x1="17.6" y1="17.6" x2="19.8" y2="19.8" stroke="#000" stroke-width="2" stroke-linecap="round" />
    <line x1="4.2" y1="19.8" x2="6.4" y2="17.6" stroke="#000" stroke-width="2" stroke-linecap="round" />
    <line x1="17.6" y1="6.4" x2="19.8" y2="4.2" stroke="#000" stroke-width="2" stroke-linecap="round" />
  </svg>
{% elsif c <= 2 %}
  {% comment %} Partly Cloudy {% endcomment %}
  <svg viewBox="0 0 24 24" width="100%" height="100%">
    <circle cx="8" cy="8" r="4" fill="none" stroke="#000" stroke-width="2" />
    <path d="M7 19 A 4 4 0 0 1 7 11 A 5 5 0 0 1 17 11 A 4 4 0 0 1 17 19 Z" fill="#000" />
  </svg>
{% elsif c == 3 %}
  {% comment %} Overcast {% endcomment %}
  <svg viewBox="0 0 24 24" width="100%" height="100%">
    <path d="M6 18 A 4 4 0 0 1 6 10 A 5 5 0 0 1 18 10 A 4 4 0 0 1 18 18 Z" fill="#000" />
  </svg>
{% elsif c >= 45 and c <= 48 %}
  {% comment %} Fog {% endcomment %}
  <svg viewBox="0 0 24 24" width="100%" height="100%">
    <line x1="3" y1="8" x2="21" y2="8" stroke="#000" stroke-width="2.5" stroke-linecap="round" />
    <line x1="5" y1="12" x2="19" y2="12" stroke="#000" stroke-width="2.5" stroke-linecap="round" />
    <line x1="3" y1="16" x2="21" y2="16" stroke="#000" stroke-width="2.5" stroke-linecap="round" />
  </svg>
{% elsif c >= 51 and c <= 67 %}
  {% comment %} Drizzle / Rain {% endcomment %}
  <svg viewBox="0 0 24 24" width="100%" height="100%">
    <path d="M5 13 A 3.5 3.5 0 0 1 5 6 A 4.5 4.5 0 0 1 17 6 A 3.5 3.5 0 0 1 17 13 Z" fill="#000" />
    <line x1="7" y1="16" x2="5" y2="21" stroke="#000" stroke-width="2" stroke-linecap="round" />
    <line x1="12" y1="16" x2="10" y2="21" stroke="#000" stroke-width="2" stroke-linecap="round" />
    <line x1="17" y1="16" x2="15" y2="21" stroke="#000" stroke-width="2" stroke-linecap="round" />
  </svg>
{% elsif c >= 71 and c <= 77 %}
  {% comment %} Snow {% endcomment %}
  <svg viewBox="0 0 24 24" width="100%" height="100%">
    <path d="M5 13 A 3.5 3.5 0 0 1 5 6 A 4.5 4.5 0 0 1 17 6 A 3.5 3.5 0 0 1 17 13 Z" fill="#000" />
    <circle cx="7" cy="18" r="1.5" fill="#000" />
    <circle cx="12" cy="19" r="1.5" fill="#000" />
    <circle cx="17" cy="18" r="1.5" fill="#000" />
  </svg>
{% elsif c >= 80 and c <= 82 %}
  {% comment %} Showers {% endcomment %}
  <svg viewBox="0 0 24 24" width="100%" height="100%">
    <path d="M5 12 A 3.5 3.5 0 0 1 5 5 A 4.5 4.5 0 0 1 17 5 A 3.5 3.5 0 0 1 17 12 Z" fill="#000" />
    <line x1="6" y1="15" x2="4" y2="21" stroke="#000" stroke-width="2.5" stroke-linecap="round" />
    <line x1="11" y1="15" x2="9" y2="21" stroke="#000" stroke-width="2.5" stroke-linecap="round" />
    <line x1="16" y1="15" x2="14" y2="21" stroke="#000" stroke-width="2.5" stroke-linecap="round" />
  </svg>
{% elsif c >= 95 %}
  {% comment %} Thunderstorm {% endcomment %}
  <svg viewBox="0 0 24 24" width="100%" height="100%">
    <path d="M5 12 A 3.5 3.5 0 0 1 5 5 A 4.5 4.5 0 0 1 17 5 A 3.5 3.5 0 0 1 17 12 Z" fill="#000" />
    <polygon points="12,13 8,19 12,19 10,23 16,17 12,17" fill="#000" />
  </svg>
{% else %}
  {% comment %} Default Cloud {% endcomment %}
  <svg viewBox="0 0 24 24" width="100%" height="100%">
    <path d="M6 18 A 4 4 0 0 1 6 10 A 5 5 0 0 1 18 10 A 4 4 0 0 1 18 18 Z" fill="#000" />
  </svg>
{% endif %}
{% endtemplate %}","full.liquid":"{% assign zip_info = IDX_0 %}
